%!  r_plot_area(+RPlot, +X:list(float), +Y:list(float), -Result:r_plot) is det.
%!  r_plot_area(+RPlot, +X:list(float), +Y:list(float), +Baseline:float, -Result:r_plot) is det.
%!  r_plot_area(+RPlot, +X:list(float), +Y:list(float), +Baseline:float, +Color:rgb, -Result:r_plot) is det.
%
%   Fills the area between a curve and a baseline.
%
%   Calls the C++ method `datamunge::graphics::RPlot::area`.
%
%   Requires strictly increasing x and at least two samples. Supports excursions above and below the baseline.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().area({0, 1}, {2, 4});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://ggplot2.tidyverse.org/reference/geom_ribbon.html
%
%   Arguments left out take the C++ defaults: Baseline = 0.0, Color = C++ default.
%
%   @arg X Horizontal coordinates.
%   @arg Y Vertical coordinates.
%   @arg Baseline Baseline in y data units.
%   @arg Color Fill color, including opacity.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_area(RPlot, X, Y, Result) :-
    '$rosetta_call'(600, [RPlot, X, Y], Result).
r_plot_area(RPlot, X, Y, Baseline, Result) :-
    '$rosetta_call'(600, [RPlot, X, Y, Baseline], Result).
r_plot_area(RPlot, X, Y, Baseline, Color, Result) :-
    '$rosetta_call'(600, [RPlot, X, Y, Baseline, Color], Result).

%!  r_plot_ribbon(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), -Result:r_plot) is det.
%!  r_plot_ribbon(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), +Color:rgb, -Result:r_plot) is det.
%
%   Fills the band between lower and upper curves.
%
%   Calls the C++ method `datamunge::graphics::RPlot::ribbon`.
%
%   Requires at least two strictly increasing x coordinates and lower <= upper at each x.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().ribbon({0, 1}, {1, 2}, {3, 4});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://ggplot2.tidyverse.org/reference/geom_ribbon.html
%
%   Arguments left out take the C++ defaults: Color = C++ default.
%
%   @arg X Horizontal coordinates.
%   @arg Lower Lower endpoint at each x.
%   @arg Upper Upper endpoint at each x.
%   @arg Color Fill color, including opacity.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_ribbon(RPlot, X, Lower, Upper, Result) :-
    '$rosetta_call'(601, [RPlot, X, Lower, Upper], Result).
r_plot_ribbon(RPlot, X, Lower, Upper, Color, Result) :-
    '$rosetta_call'(601, [RPlot, X, Lower, Upper, Color], Result).

%!  r_plot_error_bars(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), -Result:r_plot) is det.
%!  r_plot_error_bars(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), +CapWidth:float, -Result:r_plot) is det.
%!  r_plot_error_bars(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), +CapWidth:float, +Color:rgb, -Result:r_plot) is det.
%!  r_plot_error_bars(+RPlot, +X:list(float), +Lower:list(float), +Upper:list(float), +CapWidth:float, +Color:rgb, +StrokeWidth:float, -Result:r_plot) is det.
%
%   Adds vertical intervals with horizontal end caps.
%
%   Calls the C++ method `datamunge::graphics::RPlot::error_bars`.
%
%   A zero cap width draws plain intervals. Lower endpoints must be <= upper endpoints.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().error_bars({1}, {2}, {4});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://ggplot2.tidyverse.org/reference/geom_linerange.html
%
%   Arguments left out take the C++ defaults: CapWidth = 0.12, Color = C++ default, StrokeWidth = 2.0.
%
%   @arg X Horizontal coordinates.
%   @arg Lower Lower endpoint at each x.
%   @arg Upper Upper endpoint at each x.
%   @arg CapWidth Full cap width in x data units.
%   @arg Color Mark color.
%   @arg StrokeWidth Stroke width in pixels.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_error_bars(RPlot, X, Lower, Upper, Result) :-
    '$rosetta_call'(602, [RPlot, X, Lower, Upper], Result).
r_plot_error_bars(RPlot, X, Lower, Upper, CapWidth, Result) :-
    '$rosetta_call'(602, [RPlot, X, Lower, Upper, CapWidth], Result).
r_plot_error_bars(RPlot, X, Lower, Upper, CapWidth, Color, Result) :-
    '$rosetta_call'(602, [RPlot, X, Lower, Upper, CapWidth, Color], Result).
r_plot_error_bars(RPlot, X, Lower, Upper, CapWidth, Color, StrokeWidth, Result) :-
    '$rosetta_call'(602, [RPlot, X, Lower, Upper, CapWidth, Color, StrokeWidth], Result).

%!  r_plot_rectangles(+RPlot, +Left:list(float), +Bottom:list(float), +Right:list(float), +Top:list(float), -Result:r_plot) is det.
%!  r_plot_rectangles(+RPlot, +Left:list(float), +Bottom:list(float), +Right:list(float), +Top:list(float), +Label:string, -Result:r_plot) is det.
%!  r_plot_rectangles(+RPlot, +Left:list(float), +Bottom:list(float), +Right:list(float), +Top:list(float), +Label:string, +Color:rgb, -Result:r_plot) is det.
%
%   Adds filled rectangles defined by data-space bounds.
%
%   Calls the C++ method `datamunge::graphics::RPlot::rectangles`.
%
%   One rectangle per matched row. Lower bounds must be <= corresponding upper bounds.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().rectangles({0}, {1}, {2}, {3});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/rect.html
%
%   Arguments left out take the C++ defaults: Label = "", Color = C++ default.
%
%   @arg Left Left x bounds.
%   @arg Bottom Lower y bounds.
%   @arg Right Right x bounds.
%   @arg Top Upper y bounds.
%   @arg Label Optional legend label.
%   @arg Color Fill color, including opacity.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_rectangles(RPlot, Left, Bottom, Right, Top, Result) :-
    '$rosetta_call'(603, [RPlot, Left, Bottom, Right, Top], Result).
r_plot_rectangles(RPlot, Left, Bottom, Right, Top, Label, Result) :-
    '$rosetta_call'(603, [RPlot, Left, Bottom, Right, Top, Label], Result).
r_plot_rectangles(RPlot, Left, Bottom, Right, Top, Label, Color, Result) :-
    '$rosetta_call'(603, [RPlot, Left, Bottom, Right, Top, Label, Color], Result).

%!  r_plot_horizontal_bars(+RPlot, +Positions:list(float), +Values:list(float), -Result:r_plot) is det.
%!  r_plot_horizontal_bars(+RPlot, +Positions:list(float), +Values:list(float), +Label:string, -Result:r_plot) is det.
%!  r_plot_horizontal_bars(+RPlot, +Positions:list(float), +Values:list(float), +Label:string, +Color:rgb, -Result:r_plot) is det.
%!  r_plot_horizontal_bars(+RPlot, +Positions:list(float), +Values:list(float), +Label:string, +Color:rgb, +BarHeight:float, -Result:r_plot) is det.
%
%   Adds horizontal bars anchored at x = 0.
%
%   Calls the C++ method `datamunge::graphics::RPlot::horizontal_bars`.
%
%   Positions are y centers. Negative values extend left of zero.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().horizontal_bars({0, 1}, {2, -4});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   Arguments left out take the C++ defaults: Label = "", Color = C++ default, BarHeight = 0.8.
%
%   @arg Positions Bar centers along y.
%   @arg Values Bar ends along x.
%   @arg Label Optional legend label.
%   @arg Color Mark color.
%   @arg BarHeight Bar height in y data units.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_horizontal_bars(RPlot, Positions, Values, Result) :-
    '$rosetta_call'(604, [RPlot, Positions, Values], Result).
r_plot_horizontal_bars(RPlot, Positions, Values, Label, Result) :-
    '$rosetta_call'(604, [RPlot, Positions, Values, Label], Result).
r_plot_horizontal_bars(RPlot, Positions, Values, Label, Color, Result) :-
    '$rosetta_call'(604, [RPlot, Positions, Values, Label, Color], Result).
r_plot_horizontal_bars(RPlot, Positions, Values, Label, Color, BarHeight, Result) :-
    '$rosetta_call'(604, [RPlot, Positions, Values, Label, Color, BarHeight], Result).

%!  r_plot_grouped_bars(+RPlot, +X:list(float), +Values:list(list(float)), -Result:r_plot) is det.
%!  r_plot_grouped_bars(+RPlot, +X:list(float), +Values:list(list(float)), +Labels:list(string), -Result:r_plot) is det.
%!  r_plot_grouped_bars(+RPlot, +X:list(float), +Values:list(list(float)), +Labels:list(string), +Colors:list(rgb), -Result:r_plot) is det.
%!  r_plot_grouped_bars(+RPlot, +X:list(float), +Values:list(list(float)), +Labels:list(string), +Colors:list(rgb), +GroupWidth:float, -Result:r_plot) is det.
%
%   Adds adjacent bars for multiple series at each category.
%
%   Calls the C++ method `datamunge::graphics::RPlot::grouped_bars`.
%
%   Uses equal subdivisions of the group width. All rows must match the category count.
%   Labels, if supplied, must match the series count. An empty palette uses default colors.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().grouped_bars({0, 1}, {{1, 2}, {3, 4}});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/barplot.html
%
%   Arguments left out take the C++ defaults: Labels = C++ default, Colors = C++ default, GroupWidth = 0.8.
%
%   @arg X Horizontal coordinates.
%   @arg Values One row per series, one column per category.
%   @arg Labels Optional series labels.
%   @arg Colors Optional palette, recycled across series.
%   @arg GroupWidth Total group width in x data units.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_grouped_bars(RPlot, X, Values, Result) :-
    '$rosetta_call'(605, [RPlot, X, Values], Result).
r_plot_grouped_bars(RPlot, X, Values, Labels, Result) :-
    '$rosetta_call'(605, [RPlot, X, Values, Labels], Result).
r_plot_grouped_bars(RPlot, X, Values, Labels, Colors, Result) :-
    '$rosetta_call'(605, [RPlot, X, Values, Labels, Colors], Result).
r_plot_grouped_bars(RPlot, X, Values, Labels, Colors, GroupWidth, Result) :-
    '$rosetta_call'(605, [RPlot, X, Values, Labels, Colors, GroupWidth], Result).

%!  r_plot_stacked_bars(+RPlot, +X:list(float), +Values:list(list(float)), -Result:r_plot) is det.
