%   *Example*
%
%   ==
%   auto plot = dm::Plot().bubbles({1, 2}, {3, 4}, {5, 9});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   Arguments left out take the C++ defaults: Label = "", Color = C++ default.
%
%   @arg X Horizontal coordinates.
%   @arg Y Vertical coordinates.
%   @arg Radii Nonnegative marker radii in pixels.
%   @arg Label Optional legend label.
%   @arg Color Fill color, including opacity.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_bubbles(RPlot, X, Y, Radii, Result) :-
    '$rosetta_call'(612, [RPlot, X, Y, Radii], Result).
r_plot_bubbles(RPlot, X, Y, Radii, Label, Result) :-
    '$rosetta_call'(612, [RPlot, X, Y, Radii, Label], Result).
r_plot_bubbles(RPlot, X, Y, Radii, Label, Color, Result) :-
    '$rosetta_call'(612, [RPlot, X, Y, Radii, Label, Color], Result).

%!  r_plot_arrows(+RPlot, +X:list(float), +Y:list(float), +Dx:list(float), +Dy:list(float), -Result:r_plot) is det.
%!  r_plot_arrows(+RPlot, +X:list(float), +Y:list(float), +Dx:list(float), +Dy:list(float), +HeadFraction:float, -Result:r_plot) is det.
%!  r_plot_arrows(+RPlot, +X:list(float), +Y:list(float), +Dx:list(float), +Dy:list(float), +HeadFraction:float, +Color:rgb, -Result:r_plot) is det.
%!  r_plot_arrows(+RPlot, +X:list(float), +Y:list(float), +Dx:list(float), +Dy:list(float), +HeadFraction:float, +Color:rgb, +StrokeWidth:float, -Result:r_plot) is det.
%
%   Adds one arrow for each data-space displacement vector.
%
%   Calls the C++ method `datamunge::graphics::RPlot::arrows`.
%
%   The two head strokes are computed in data coordinates, so axis scaling affects their
%   displayed angles. Zero-length arrows are omitted.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().arrows({0}, {0}, {1}, {2});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/arrows.html
%
%   Arguments left out take the C++ defaults: HeadFraction = 0.22, Color = C++ default, StrokeWidth = 2.0.
%
%   @arg X Horizontal coordinates.
%   @arg Y Vertical coordinates.
%   @arg Dx Horizontal displacements.
%   @arg Dy Vertical displacements.
%   @arg HeadFraction Backward head length as a fraction of the shaft, in [0, 1].
%   @arg Color Mark color.
%   @arg StrokeWidth Stroke width in pixels.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
r_plot_arrows(RPlot, X, Y, Dx, Dy, Result) :-
    '$rosetta_call'(613, [RPlot, X, Y, Dx, Dy], Result).
r_plot_arrows(RPlot, X, Y, Dx, Dy, HeadFraction, Result) :-
    '$rosetta_call'(613, [RPlot, X, Y, Dx, Dy, HeadFraction], Result).
r_plot_arrows(RPlot, X, Y, Dx, Dy, HeadFraction, Color, Result) :-
    '$rosetta_call'(613, [RPlot, X, Y, Dx, Dy, HeadFraction, Color], Result).
r_plot_arrows(RPlot, X, Y, Dx, Dy, HeadFraction, Color, StrokeWidth, Result) :-
    '$rosetta_call'(613, [RPlot, X, Y, Dx, Dy, HeadFraction, Color, StrokeWidth], Result).

%!  r_plot_contour(+RPlot, +X:list(float), +Y:list(float), +Z:list(list(float)), +Level:float, -Result:r_plot) is det.
%!  r_plot_contour(+RPlot, +X:list(float), +Y:list(float), +Z:list(list(float)), +Level:float, +Color:rgb, -Result:r_plot) is det.
%!  r_plot_contour(+RPlot, +X:list(float), +Y:list(float), +Z:list(list(float)), +Level:float, +Color:rgb, +StrokeWidth:float, -Result:r_plot) is det.
%
%   Adds the contour of a sampled scalar field at a given level.
%
%   Calls the C++ method `datamunge::graphics::RPlot::contour`.
%
%   Uses marching squares, mapping tile intersections to the supplied coordinates.
%   A level with no intersections adds no marks. Requires two increasing coordinates per axis.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().contour({0, 1}, {0, 1}, {{0, 1}, {0, 1}}, 0.5);
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/contour.html
%
%   Arguments left out take the C++ defaults: Color = C++ default, StrokeWidth = 2.0.
%
%   @arg X Horizontal coordinates.
%   @arg Y Vertical coordinates.
%   @arg Z Finite grid indexed as z[y index][x index].
%   @arg Level Scalar contour level.
%   @arg Color Mark color.
%   @arg StrokeWidth Stroke width in pixels.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For empty, nonfinite, mismatched or invalid inputs.
%   @throws error(native_error(length_error, Message), _) (C++ `std::length_error`): If the grid geometry is unrepresentable.
r_plot_contour(RPlot, X, Y, Z, Level, Result) :-
    '$rosetta_call'(614, [RPlot, X, Y, Z, Level], Result).
r_plot_contour(RPlot, X, Y, Z, Level, Color, Result) :-
    '$rosetta_call'(614, [RPlot, X, Y, Z, Level, Color], Result).
r_plot_contour(RPlot, X, Y, Z, Level, Color, StrokeWidth, Result) :-
    '$rosetta_call'(614, [RPlot, X, Y, Z, Level, Color, StrokeWidth], Result).

%!  r_plot_candlesticks(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), -Result:r_plot) is det.
%!  r_plot_candlesticks(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, -Result:r_plot) is det.
%!  r_plot_candlesticks(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, +Rising:rgb, -Result:r_plot) is det.
%!  r_plot_candlesticks(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, +Rising:rgb, +Falling:rgb, -Result:r_plot) is det.
%
%   Draws open-to-close bodies with low-to-high wicks.
%
%   Calls the C++ method `datamunge::graphics::RPlot::candlesticks`.
%
%   Positions must strictly increase. If open equals close, draws a horizontal doji mark.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().candlesticks({0}, {2}, {4}, {1}, {3});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   *References*
%
%     - https://plotly.com/python/candlestick-charts/
%
%   Arguments left out take the C++ defaults: Width = 0.6, Rising = C++ default, Falling = C++ default.
%
%   @arg X Positions in x data units.
%   @arg Open Opening values.
%   @arg High Upper endpoints.
%   @arg Low Lower endpoints.
%   @arg Close Closing values.
%   @arg Width Full body or tick span in x data units.
%   @arg Rising Color when close is at or above open.
%   @arg Falling Color when close is below open.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If data or geometry is empty, mismatched, nonfinite or invalid.
r_plot_candlesticks(RPlot, X, Open, High, Low, Close, Result) :-
    '$rosetta_call'(615, [RPlot, X, Open, High, Low, Close], Result).
r_plot_candlesticks(RPlot, X, Open, High, Low, Close, Width, Result) :-
    '$rosetta_call'(615, [RPlot, X, Open, High, Low, Close, Width], Result).
r_plot_candlesticks(RPlot, X, Open, High, Low, Close, Width, Rising, Result) :-
    '$rosetta_call'(615, [RPlot, X, Open, High, Low, Close, Width, Rising], Result).
r_plot_candlesticks(RPlot, X, Open, High, Low, Close, Width, Rising, Falling, Result) :-
    '$rosetta_call'(615, [RPlot, X, Open, High, Low, Close, Width, Rising, Falling], Result).

%!  r_plot_ohlc(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), -Result:r_plot) is det.
%!  r_plot_ohlc(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, -Result:r_plot) is det.
%!  r_plot_ohlc(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, +Rising:rgb, -Result:r_plot) is det.
%!  r_plot_ohlc(+RPlot, +X:list(float), +Open:list(float), +High:list(float), +Low:list(float), +Close:list(float), +Width:float, +Rising:rgb, +Falling:rgb, -Result:r_plot) is det.
%
%   Draws low-to-high bars with a left opening tick and a right closing tick.
%
%   Calls the C++ method `datamunge::graphics::RPlot::ohlc`.
%
%   Positions must strictly increase.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().ohlc({0}, {2}, {4}, {1}, {3});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://plotly.com/python/ohlc-charts/
%
%   Arguments left out take the C++ defaults: Width = 0.6, Rising = C++ default, Falling = C++ default.
%
%   @arg X Positions in x data units.
%   @arg Open Opening values.
%   @arg High Upper endpoints.
%   @arg Low Lower endpoints.
%   @arg Close Closing values.
%   @arg Width Full body or tick span in x data units.
%   @arg Rising Color when close is at or above open.
%   @arg Falling Color when close is below open.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If data or geometry is empty, mismatched, nonfinite or invalid.
