    '$rosetta_call'(616, [RPlot, X, Open, High, Low, Close], Result).
r_plot_ohlc(RPlot, X, Open, High, Low, Close, Width, Result) :-
    '$rosetta_call'(616, [RPlot, X, Open, High, Low, Close, Width], Result).
r_plot_ohlc(RPlot, X, Open, High, Low, Close, Width, Rising, Result) :-
    '$rosetta_call'(616, [RPlot, X, Open, High, Low, Close, Width, Rising], Result).
r_plot_ohlc(RPlot, X, Open, High, Low, Close, Width, Rising, Falling, Result) :-
    '$rosetta_call'(616, [RPlot, X, Open, High, Low, Close, Width, Rising, Falling], Result).

