%!  r_plot_qqplot(+RPlot, +X:list(float), +Y:list(float), -Result:r_plot) is det.
%!  r_plot_qqplot(+RPlot, +X:list(float), +Y:list(float), +Color:rgb, -Result:r_plot) is det.
%
%   Plots the empirical quantiles of two samples.
%
%   Calls the C++ method `datamunge::graphics::RPlot::qqplot`.
%
%   Uses the shorter sample size as the number of equally spaced probabilities including 0 and 1. Interpolates between ordered values. Each sample must have at least two observations.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().qqplot({1, 2, 3}, {2, 4});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/stats/html/qqnorm.html
%
%   Arguments left out take the C++ defaults: Color = C++ default.
%
%   @arg X Sample for the horizontal axis.
%   @arg Y Sample for the vertical axis.
%   @arg Color Layer color.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_qqplot(RPlot, X, Y, Result) :-
    '$rosetta_call'(621, [RPlot, X, Y], Result).
r_plot_qqplot(RPlot, X, Y, Color, Result) :-
    '$rosetta_call'(621, [RPlot, X, Y, Color], Result).

%!  r_plot_bland_altman(+RPlot, +First:list(float), +Second:list(float), -Result:r_plot) is det.
%!  r_plot_bland_altman(+RPlot, +First:list(float), +Second:list(float), +Color:rgb, -Result:r_plot) is det.
%
%   Plots paired differences against paired means.
%
%   Calls the C++ method `datamunge::graphics::RPlot::bland_altman`.
%
%   Adds the mean difference and limits at mean difference ± 1.96 sample standard deviations. Requires two or more pairs.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().bland_altman({1, 2}, {1, 3});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://doi.org/10.1016/S0140-6736(86)90837-8
%
%   Arguments left out take the C++ defaults: Color = C++ default.
%
%   @arg First First measurements.
%   @arg Second Second measurements, subtracted from the first.
%   @arg Color Layer color.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_bland_altman(RPlot, First, Second, Result) :-
    '$rosetta_call'(622, [RPlot, First, Second], Result).
r_plot_bland_altman(RPlot, First, Second, Color, Result) :-
    '$rosetta_call'(622, [RPlot, First, Second, Color], Result).

%!  r_plot_autocorrelation(+RPlot, +Sample:list(float), +MaxLag:integer, -Result:r_plot) is det.
%!  r_plot_autocorrelation(+RPlot, +Sample:list(float), +MaxLag:integer, +Partial:boolean, -Result:r_plot) is det.
%!  r_plot_autocorrelation(+RPlot, +Sample:list(float), +MaxLag:integer, +Partial:boolean, +Color:rgb, -Result:r_plot) is det.
%
%   Plots sample autocorrelations as vertical stems.
%
%   Calls the C++ method `datamunge::graphics::RPlot::autocorrelation`.
%
%   Full autocorrelation starts at lag zero. Partial autocorrelation starts at lag one. Uses the core time-series estimators.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().autocorrelation({1, 4, 2, 1}, 2);
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   *References*
%
%     - https://stat.ethz.ch/R-manual/R-devel/library/stats/html/acf.html
%
%   Arguments left out take the C++ defaults: Partial = false, Color = C++ default.
%
%   @arg Sample Finite, nonconstant series with at least two samples.
%   @arg MaxLag Largest lag, less than the series length.
%   @arg Partial Draw the partial autocorrelation when true.
%   @arg Color Layer color.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_autocorrelation(RPlot, Sample, MaxLag, Result) :-
    '$rosetta_call'(623, [RPlot, Sample, MaxLag], Result).
r_plot_autocorrelation(RPlot, Sample, MaxLag, Partial, Result) :-
    '$rosetta_call'(623, [RPlot, Sample, MaxLag, Partial], Result).
r_plot_autocorrelation(RPlot, Sample, MaxLag, Partial, Color, Result) :-
    '$rosetta_call'(623, [RPlot, Sample, MaxLag, Partial, Color], Result).

