    '$rosetta_call'(628, [RPlot, Values], Result).
r_plot_ternary(RPlot, Values, Labels, Result) :-
    '$rosetta_call'(628, [RPlot, Values, Labels], Result).
r_plot_ternary(RPlot, Values, Labels, Color, Result) :-
    '$rosetta_call'(628, [RPlot, Values, Labels, Color], Result).

