%!  r_plot_treemap(+RPlot, +Weights:list(float), -Result:r_plot) is det.
%!  r_plot_treemap(+RPlot, +Weights:list(float), +Labels:list(string), -Result:r_plot) is det.
%!  r_plot_treemap(+RPlot, +Weights:list(float), +Labels:list(string), +Colors:list(rgb), -Result:r_plot) is det.
%
%   Partitions a rectangle into area-proportional tiles.
%
%   Calls the C++ method `datamunge::graphics::RPlot::treemap`.
%
%   Recursively splits the longer side, keeping input order and choosing the split nearest half the weight. Tiles occupy [0, 1] on both axes.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().treemap({1, 3});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   Arguments left out take the C++ defaults: Labels = C++ default, Colors = C++ default.
%
%   @arg Weights Strictly positive finite weights, with a finite sum.
%   @arg Labels Optional centered labels in input order.
%   @arg Colors Optional palette, recycled. An empty palette uses built-in categorical colors.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_treemap(RPlot, Weights, Result) :-
    '$rosetta_call'(630, [RPlot, Weights], Result).
r_plot_treemap(RPlot, Weights, Labels, Result) :-
    '$rosetta_call'(630, [RPlot, Weights, Labels], Result).
r_plot_treemap(RPlot, Weights, Labels, Colors, Result) :-
    '$rosetta_call'(630, [RPlot, Weights, Labels, Colors], Result).

%!  r_plot_arc_diagram(+RPlot, +Positions:list(float), +From:list(integer), +To:list(integer), -Result:r_plot) is det.
%!  r_plot_arc_diagram(+RPlot, +Positions:list(float), +From:list(integer), +To:list(integer), +Color:rgb, -Result:r_plot) is det.
%
%   Connects nodes on a single horizontal baseline with semicircular arcs.
%
%   Calls the C++ method `datamunge::graphics::RPlot::arc_diagram`.
%
%   Positions must strictly increase. Edges are pairs of zero-based indices. Self-loops are invalid.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().arc_diagram({0, 1}, {0}, {1});
%   std::print("{}\n", plot.series().size());  // 2
%   ==
%
%   Arguments left out take the C++ defaults: Color = C++ default.
%
%   @arg Positions Node positions.
%   @arg From First endpoint index per edge.
%   @arg To Second endpoint index per edge.
%   @arg Color Layer color.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_arc_diagram(RPlot, Positions, From, To, Result) :-
    '$rosetta_call'(631, [RPlot, Positions, From, To], Result).
r_plot_arc_diagram(RPlot, Positions, From, To, Color, Result) :-
    '$rosetta_call'(631, [RPlot, Positions, From, To, Color], Result).

%!  r_plot_choropleth(+RPlot, +X:list(list(float)), +Y:list(list(float)), +Values:list(float), -Result:r_plot) is det.
%!  r_plot_choropleth(+RPlot, +X:list(list(float)), +Y:list(list(float)), +Values:list(float), +Palette:list(rgb), -Result:r_plot) is det.
%
%   Colors region polygons on one shared numeric scale.
%
%   Calls the C++ method `datamunge::graphics::RPlot::choropleth`.
%
%   Coordinates are supplied in the desired projection. Each polygon is an outer ring. Provide separate rings with the same value for disconnected parts of a region.
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().choropleth({{0, 1, 0}}, {{0, 0, 1}}, {2});
%   std::print("{}\n", plot.series().size());  // 1
%   ==
%
%   Arguments left out take the C++ defaults: Palette = C++ default.
%
%   @arg X One horizontal coordinate vector per ring.
%   @arg Y One vertical coordinate vector per ring.
%   @arg Values One finite numeric value per ring.
%   @arg Palette Optional low-to-high palette; empty uses viridis.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_choropleth(RPlot, X, Y, Values, Result) :-
    '$rosetta_call'(632, [RPlot, X, Y, Values], Result).
r_plot_choropleth(RPlot, X, Y, Values, Palette, Result) :-
    '$rosetta_call'(632, [RPlot, X, Y, Values, Palette], Result).

%!  r_plot_radar(+RPlot, +Values:list(float), -Result:r_plot) is det.
%!  r_plot_radar(+RPlot, +Values:list(float), +Labels:list(string), -Result:r_plot) is det.
%!  r_plot_radar(+RPlot, +Values:list(float), +Labels:list(string), +Color:rgb, -Result:r_plot) is det.
%
%   Connects normalized values on evenly spaced radial spokes.
%
%   Calls the C++ method `datamunge::graphics::RPlot::radar`.
%
%   The first spoke points up and the remaining spokes proceed clockwise. Draws a unit frame and quarter-scale guides. Values must be in [0, 1].
%
%   *Example*
%
%   ==
%   auto plot = dm::Plot().radar({0.2, 0.5, 0.8});
%   std::print("{}\n", plot.series().size());  // 6
%   ==
%
%   Arguments left out take the C++ defaults: Labels = C++ default, Color = C++ default.
%
%   @arg Values At least three normalized values.
%   @arg Labels Optional labels, one per spoke.
%   @arg Color Layer color.
%   @arg Result This plot, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched, nonfinite or invalid input.
r_plot_radar(RPlot, Values, Result) :-
    '$rosetta_call'(633, [RPlot, Values], Result).
r_plot_radar(RPlot, Values, Labels, Result) :-
    '$rosetta_call'(633, [RPlot, Values, Labels], Result).
r_plot_radar(RPlot, Values, Labels, Color, Result) :-
    '$rosetta_call'(633, [RPlot, Values, Labels, Color], Result).

% ---------------------------------------------------------------- r_layout
%
%   Tiles independently built plots into one multi-panel figure, like R's
%   `par(mfrow = c(rows, cols))` followed by one plot per panel.
%
%   Wraps the C++ class `datamunge::graphics::RLayout`.
%
%   Create it with create(rows, cols), then add() up to rows * cols panels; they fill the grid
%   row by row. Each panel is copied (and its SVG rendered) at add() time, so later changes to
%   the original plot do not show and panels need not outlive the layout. Each cell is
%   `width / cols` by `(height - band) / rows` pixels, where band is title_band_px when a
%   figure title is set and 0 otherwise; every panel is scaled from its own canvas size into its
%   cell. The figure background is white. Unused cells stay empty.
%
%   *Example*
%
%   ==
%   const auto x = dm::seql(0.0, 6.0, 30);
%   auto fig = dm::graphics::RLayout::create(1, 2)
%                  .size(1200, 500)
%                  .title("Two views")
%                  .add(dm::Plot(x, dm::sin(x)).set_title("sin"))
%                  .add(dm::Plot(x, dm::cos(x)).set_title("cos"));
%   std::print("{} panels in {}x{}\n", fig.panel_count(), fig.rows(), fig.cols());
%   // 2 panels in 1x2
%   fig.save("two_views.svg");
%   ==
%
%   *References*
%
%     - R `par()` (`mfrow`): https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/par.html

%!  r_layout_new(-Object:r_layout) is det.
%
%   Calls the C++ constructor `datamunge::graphics::RLayout`.
r_layout_new(Object) :-
    '$rosetta_construct'(659, [], [], [], Object).

%!  r_layout_create(+Rows:integer, +Cols:integer, -Result:r_layout) is det.
%
%   Creates an empty layout with `rows` by `cols` cells, like R's
%   `par(mfrow = c(rows, cols))`.
%
%   Calls the C++ method `datamunge::graphics::RLayout::create`.
%
%   The figure starts at 960 by 640 pixels with no title.
%
%   *Example*
%
%   See RLayout.
%
%   *References*
%
%     - R `par()` (`mfrow`): https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/par.html
%
%   @arg Rows Number of panel rows; must be positive.
%   @arg Cols Number of panel columns; must be positive.
%   @arg Result The empty layout.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If `rows` or `cols` is 0.
%   @see `add()`
r_layout_create(Rows, Cols, Result) :-
    '$rosetta_call'(635, [Rows, Cols], Result).

%!  r_layout_add(+RLayout, +Panel:plot, -Result:r_layout) is det.
%
%   Copies `panel` into the next free cell, filling rows left to right, top to bottom.
%
%   Calls the C++ method `datamunge::graphics::RLayout::add`.
%
%   The panel's SVG is rendered immediately and stored with the copy, so rendering errors
%   surface here and later edits to the original plot have no effect on the layout.
%
%   *Example*
%
%   ==
%   auto fig = dm::graphics::RLayout::create(1, 1).add(dm::Plot(dm::c(1.0, 2.0), dm::c(2.0, 1.0)));
%   try {
%     fig.add(dm::Plot(dm::c(1.0), dm::c(1.0)));
%   } catch (const std::invalid_argument& e) {
%     std::print("{}\n", e.what());  // RLayout::add: layout is already full
%   }
%   ==
%
%   @arg Panel The plot to add; any RPlot (or other Plot) converts.
%   @arg Result This layout, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If all rows * cols cells are already filled.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If `panel` has no data series or its canvas is smaller than its margins.
%   @see `panel()`, `panel_count()`
r_layout_add(RLayout, Panel, Result) :-
    '$rosetta_call'(636, [RLayout, Panel], Result).

%!  r_layout_size(+RLayout, +Width:integer, +Height:integer, -Result:r_layout) is det.
%
%   Sets the size of the whole figure in pixels (default 960 by 640).
%
%   Calls the C++ method `datamunge::graphics::RLayout::size`.
%
%   Panels keep their own canvas sizes and are scaled into their cells, so text in a panel
%   shrinks or grows with it; give panels a size close to their cell for readable labels.
%
%   *Example*
%
%   See RLayout.
%
%   @arg Width Figure width in pixels.
%   @arg Height Figure height in pixels, including the title band.
%   @arg Result This layout, for chaining.
%   @see `title()`
r_layout_size(RLayout, Width, Height, Result) :-
    '$rosetta_call'(637, [RLayout, Width, Height], Result).

%!  r_layout_dpi(+RLayout, -Result:(r_layout;float)) is det.
%!  r_layout_dpi(+RLayout, +Value:float, -Result:(r_layout;float)) is det.
%
%   Sets the resolution PNG and PDF output is rasterized at, like R's
%   `png(res = )` and ggsave()'s `dpi =` (default 96).
%
%   Calls the C++ method `datamunge::graphics::RLayout::dpi`.
%
%   The layout, text and line widths keep their size relative to the layout; only the pixel
%   count changes: a layout of width(units::inch{8}) saves as a 768-pixel-wide PNG at 96 dpi
%   and a 2400-pixel-wide one at 300 dpi. A PNG records the resolution (its pHYs chunk) so
%   other programs show it at its physical size; a PDF keeps its page size and gains detail.
%   SVG output is vector and is unaffected.
%
%   *Example*
%
%   ==
%   auto grid = dm::graphics::RLayout::create(1, 2).width(dm::units::inch{6}).dpi(300);
%   std::print("{} {}\n", grid.width(), grid.dpi());   // 576 300
%   ==
%
%   *References*
%
%     - R png() `res` argument: https://stat.ethz.ch/R-manual/R-devel/library/grDevices/html/png.html
%     - ggplot2 ggsave() `dpi` argument: https://ggplot2.tidyverse.org/reference/ggsave.html
%
%   Overloads (C++ picks one by the arguments' types):
%     - `dpi(+Value:float, -Result:r_layout)`
%     - `dpi(-Result:float)`
%
%   @arg Value Dots per inch; finite and positive.
%   @arg Result This layout, for chaining.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If `value` is not finite and positive.
%   @see `width(units::Length)`, `height(units::Length)`, `save()`
r_layout_dpi(RLayout, Result) :-
    '$rosetta_call'(638, [RLayout], Result).
r_layout_dpi(RLayout, Value, Result) :-
    '$rosetta_call'(638, [RLayout, Value], Result).

%!  r_layout_title(+RLayout, +Value:string, -Result:r_layout) is det.
%
%   Sets an optional figure-level heading drawn in a band above the panels, like R's
%   `mtext(main, outer = TRUE)`; an empty string (the default) reserves no band.
%
%   Calls the C++ method `datamunge::graphics::RLayout::title`.
%
%   *Example*
%
%   See RLayout.
%
%   *References*
%
%     - R `mtext()`: https://stat.ethz.ch/R-manual/R-devel/library/graphics/html/mtext.html
%
%   @arg Value Heading text; the band is title_band_px pixels tall.
%   @arg Result This layout, for chaining.
%   @see `title_text()`
r_layout_title(RLayout, Value, Result) :-
    '$rosetta_call'(639, [RLayout, Value], Result).

%!  r_layout_rows(+RLayout, -Result:integer) is det.
%
%   Returns the number of panel rows given to create().
%
%   Calls the C++ method `datamunge::graphics::RLayout::rows`.
%
%   @arg Result Row count (at least 1).
r_layout_rows(RLayout, Result) :-
    '$rosetta_call'(640, [RLayout], Result).

%!  r_layout_cols(+RLayout, -Result:integer) is det.
%
%   Returns the number of panel columns given to create().
%
%   Calls the C++ method `datamunge::graphics::RLayout::cols`.
%
%   @arg Result Column count (at least 1).
r_layout_cols(RLayout, Result) :-
    '$rosetta_call'(641, [RLayout], Result).

%!  r_layout_width(+RLayout, -Result:integer) is det.
%
%   Returns the figure width in pixels.
%
%   Calls the C++ method `datamunge::graphics::RLayout::width`.
%
%   @arg Result Width set by size() (default 960).
r_layout_width(RLayout, Result) :-
    '$rosetta_call'(642, [RLayout], Result).

%!  r_layout_height(+RLayout, -Result:integer) is det.
%
%   Returns the figure height in pixels.
%
%   Calls the C++ method `datamunge::graphics::RLayout::height`.
%
%   @arg Result Height set by size() (default 640).
r_layout_height(RLayout, Result) :-
    '$rosetta_call'(643, [RLayout], Result).

%!  r_layout_panel_count(+RLayout, -Result:integer) is det.
%
%   Returns how many panels have been added.
%
%   Calls the C++ method `datamunge::graphics::RLayout::panel_count`.
%
%   @arg Result Panel count, at most rows() * cols().
r_layout_panel_count(RLayout, Result) :-
    '$rosetta_call'(644, [RLayout], Result).

%!  r_layout_title_text(+RLayout, -Result:string) is det.
%
%   Borrows the figure-level heading for the lifetime of this layout.
%
%   Calls the C++ method `datamunge::graphics::RLayout::title_text`.
%
%   @arg Result The title; empty (the default) when none is drawn.
r_layout_title_text(RLayout, Result) :-
    '$rosetta_call'(645, [RLayout], Result).

%!  r_layout_panel(+RLayout, +Index:integer, -Result:plot) is det.
%
%   Borrows the copy of the `index-th` added panel.
%
%   Calls the C++ method `datamunge::graphics::RLayout::panel`.
%
%   *Example*
%
%   ==
%   auto fig = dm::graphics::RLayout::create(1, 2).add(dm::Plot(dm::c(1.0), dm::c(1.0)).set_title("A"));
%   std::print("{}\n", fig.panel(0).title_text());  // A
%   ==
%
%   @arg Index Zero-based panel index, in the order panels were added.
%   @arg Result The stored copy, valid until the next add() or the layout's destruction.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If `index` is not below panel_count().
r_layout_panel(RLayout, Index, Result) :-
    '$rosetta_call'(646, [RLayout, Index], Result).

%!  r_layout_to_svg(+RLayout, -Result:string) is det.
%
%   Renders the multi-panel figure as a standalone SVG document and returns it as a string.
%
%   Calls the C++ method `datamunge::graphics::RLayout::to_svg`.
%
%   Each panel becomes a nested `<svg>` scaled into its cell. A layout with no panels renders
%   as an empty white figure. The layout is not modified.
%
%   *Example*
%
%   ==
%   auto fig = dm::graphics::RLayout::create(2, 1).add(dm::Plot(dm::c(1.0, 2.0), dm::c(1.0, 2.0)));
%   std::print("{}\n", fig.to_svg().starts_with("<?xml"));  // true
%   ==
%
%   @arg Result The complete SVG text.
%   @see `save()`
r_layout_to_svg(RLayout, Result) :-
    '$rosetta_call'(647, [RLayout], Result).

%!  r_layout_save(+RLayout, +Path:string) is det.
%
%   Saves the figure, choosing the format from the extension: `.svg` (or none) writes
%   SVG, `.png` / `.pdf` write the same tiled raster the X11 viewer shows.
%
%   Calls the C++ method `datamunge::graphics::RLayout::save`.
%
%   The extension is case-sensitive and an existing file is overwritten. Raster panels are
%   re-rendered from the stored copies and scaled into their cells.
%
%   *Example*
%
%   See RLayout.
%
%   @arg Path Destination file.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For any other extension.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the file cannot be written.
%   @see `save_svg()`, `to_svg()`, `show()`
r_layout_save(RLayout, Path) :-
    '$rosetta_call'(648, [RLayout, Path], _).

%!  r_layout_save_svg(+RLayout, +Path:string) is det.
%
%   Writes to_svg() to `path` regardless of its extension.
%
%   Calls the C++ method `datamunge::graphics::RLayout::save_svg`.
%
%   @arg Path Destination file; an existing file is overwritten.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the file cannot be opened for writing.
%   @see `save()`
r_layout_save_svg(RLayout, Path) :-
    '$rosetta_call'(649, [RLayout, Path], _).

%!  r_layout_to_png(+RLayout, -Result:list(integer)) is det.
%
%   Renders the tiled figure as PNG image bytes (the raster save() writes for `.png`).
%
%   Calls the C++ method `datamunge::graphics::RLayout::to_png`.
%
%   @arg Result The complete PNG file contents.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If a panel cannot be rendered.
%   @see `save_png()`, `to_svg()`
r_layout_to_png(RLayout, Result) :-
    '$rosetta_call'(650, [RLayout], Result).

%!  r_layout_to_pdf(+RLayout, -Result:list(integer)) is det.
%
%   Renders the tiled figure as a one-page PDF holding the raster image.
%
%   Calls the C++ method `datamunge::graphics::RLayout::to_pdf`.
%
%   @arg Result The complete PDF file contents.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If a panel cannot be rendered.
%   @see `save_pdf()`, `to_png()`
r_layout_to_pdf(RLayout, Result) :-
    '$rosetta_call'(651, [RLayout], Result).

%!  r_layout_save_png(+RLayout, +Path:string) is det.
%
%   Writes to_png() to `path` regardless of its extension.
%
%   Calls the C++ method `datamunge::graphics::RLayout::save_png`.
%
%   @arg Path Destination file; an existing file is overwritten.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the file cannot be written or a panel cannot be rendered.
r_layout_save_png(RLayout, Path) :-
    '$rosetta_call'(652, [RLayout, Path], _).

%!  r_layout_save_pdf(+RLayout, +Path:string) is det.
%
%   Writes to_pdf() to `path` regardless of its extension.
%
%   Calls the C++ method `datamunge::graphics::RLayout::save_pdf`.
%
%   @arg Path Destination file; an existing file is overwritten.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the file cannot be written or a panel cannot be rendered.
r_layout_save_pdf(RLayout, Path) :-
    '$rosetta_call'(653, [RLayout, Path], _).

%!  r_layout_fit_panels(+RLayout, -Result:r_layout) is det.
%
%   Resizes every stored panel's canvas to its cell, so text keeps its pixel size
%   instead of being scaled with the panel.
%
%   Calls the C++ method `datamunge::graphics::RLayout::fit_panels`.
%
%   Call it after size() and title() (the title band changes the cell height). Panels added
%   later keep their own size until fit_panels() is called again. A cell whose shorter side is
%   under min_panel_px gets a canvas scaled up to that side (same aspect ratio), so its text is
%   drawn proportionally smaller instead of the margins overflowing the panel.
%
%   *Example*
%
%   ==
%   auto fig = dm::graphics::RLayout::create(1, 2)
%                  .add(dm::Plot(dm::c(1.0, 2.0), dm::c(2.0, 1.0)))
%                  .add(dm::Plot(dm::c(1.0, 2.0), dm::c(1.0, 2.0)))
%                  .size(1000, 400)
%                  .fit_panels();
%   std::print("{}x{}\n", fig.panel(0).width(), fig.panel(0).height());  // 500x400
%   ==
%
%   @arg Result This layout, for chaining.
%   @see `size()`
r_layout_fit_panels(RLayout, Result) :-
    '$rosetta_call'(654, [RLayout], Result).

%!  r_layout_show(+RLayout) is det.
%!  r_layout_show(+RLayout, +TitleHint:string) is det.
%
%   Opens the tiled figure in the interactive X11 viewer; the toolbar zoom/pan buttons
%   act on every panel's data bounds at once, keyboard zoom/pan scales the whole image.
%
%   Calls the C++ method `datamunge::graphics::RLayout::show`.
%
%   Blocks until the window is closed (q or Escape). Use save() in headless code.
%
%   *Example*
%
%   ==
%   const auto x = dm::seql(0.0, 6.0, 30);
%   dm::graphics::RLayout::create(1, 2)
%       .add(dm::Plot(x, dm::sin(x)))
%       .add(dm::Plot(x, dm::cos(x)))
%       .show("Trig");
%   ==
%
%   Arguments left out take the C++ defaults: TitleHint = "".
%
%   @arg TitleHint Window title; empty (the default) uses title_text().
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If X11 support was not enabled at build time or no display is available.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If no panel was added.
%   @see `save()`, `Plot::show()`
r_layout_show(RLayout) :-
    '$rosetta_call'(655, [RLayout], _).
r_layout_show(RLayout, TitleHint) :-
    '$rosetta_call'(655, [RLayout, TitleHint], _).

%!  r_layout_view(+RLayout) is det.
%!  r_layout_view(+RLayout, +TitleHint:string) is det.
%
%   Same as show(); kept as an alias for older code.
%
%   Calls the C++ method `datamunge::graphics::RLayout::view`.
%
%   Arguments left out take the C++ defaults: TitleHint = "".
%
%   @arg TitleHint Window title; empty (the default) uses title_text().
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): As for show().
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If no panel was added.
%   @see `show()`
r_layout_view(RLayout) :-
    '$rosetta_call'(656, [RLayout], _).
r_layout_view(RLayout, TitleHint) :-
    '$rosetta_call'(656, [RLayout, TitleHint], _).

%!  r_layout_title_band_px(-Value:integer) is det.
%
%   Height in pixels of the heading band reserved above the panels when a title is set.
%
%   The C++ constant `datamunge::graphics::RLayout::title_band_px`.
r_layout_title_band_px(Value) :-
    '$rosetta_call'(657, [], Value).

%!  r_layout_min_panel_px(-Value:integer) is det.
%
%   Smallest canvas side fit_panels() gives a panel; smaller cells get a larger canvas
%   with the cell's aspect ratio, scaled down when drawn, so the margins still fit.
%
%   The C++ constant `datamunge::graphics::RLayout::min_panel_px`.
r_layout_min_panel_px(Value) :-
    '$rosetta_call'(658, [], Value).

% ---------------------------------------------------------------- gibbs_options
%
%   Settings for GibbsSampler.
%
%   Wraps the C++ class `datamunge::bayes::GibbsOptions`.

%!  gibbs_options_new(-Object:gibbs_options) is det.
%
%   Calls the C++ constructor `datamunge::bayes::GibbsOptions`.
gibbs_options_new(Object) :-
    '$rosetta_construct'(670, [], [], [], Object).

%!  gibbs_options_num_samples(+GibbsOptions, -Value:integer) is det.
%
%   Number of post-warmup sweeps kept. (integer).
