image_loader_width(ImageLoader, Result) :-
    '$rosetta_call'(878, [ImageLoader], Result).

%!  image_loader_channels(+ImageLoader, -Result:integer) is det.
%
%   Channels per pixel: 1 for MNIST-style, 3 (RGB) for CIFAR.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::channels`.
image_loader_channels(ImageLoader, Result) :-
    '$rosetta_call'(879, [ImageLoader], Result).

%!  image_loader_num_classes(+ImageLoader, -Result:integer) is det.
%
%   Number of label classes (CIFAR-100: 100, or 20 with coarse labels).
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::num_classes`.
image_loader_num_classes(ImageLoader, Result) :-
    '$rosetta_call'(880, [ImageLoader], Result).

%!  image_loader_class_names(+ImageLoader, -Result:list(string)) is det.
%
%   Label names, indexed by label (e.g. "airplane" for CIFAR-10 label 0).
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::class_names`.
image_loader_class_names(ImageLoader, Result) :-
    '$rosetta_call'(881, [ImageLoader], Result).

%!  image_loader_epoch(+ImageLoader, -Result:integer) is det.
%
%   The current epoch number, starting at 0 and advanced by reset().
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::epoch`.
image_loader_epoch(ImageLoader, Result) :-
    '$rosetta_call'(882, [ImageLoader], Result).

%!  image_loader_position(+ImageLoader, -Result:integer) is det.
%
%   Index of the batch next() will return in this epoch.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::position`.
image_loader_position(ImageLoader, Result) :-
    '$rosetta_call'(883, [ImageLoader], Result).

%!  image_loader_has_next(+ImageLoader, -Result:boolean) is det.
%
%   true while the current epoch has batches left.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::has_next`.
image_loader_has_next(ImageLoader, Result) :-
    '$rosetta_call'(884, [ImageLoader], Result).

%!  image_loader_next(+ImageLoader, -Result:image_batch) is det.
%
%   Reads the next batch of the current epoch.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::next`.
%
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): when the epoch is finished (call reset() for the next one).
image_loader_next(ImageLoader, Result) :-
    '$rosetta_call'(885, [ImageLoader], Result).

%!  image_loader_reset(+ImageLoader) is det.
%
%   Starts the next epoch: the position returns to 0 and, if shuffling, a new
%   order is drawn.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::reset`.
image_loader_reset(ImageLoader) :-
    '$rosetta_call'(886, [ImageLoader], _).

%!  image_loader_batch(+ImageLoader, +Index:integer, -Result:image_batch) is det.
%
%   Reads batch `index` of the current epoch without moving the position.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::batch`.
%
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): if `index` is not in [0, num_batches()).
image_loader_batch(ImageLoader, Index, Result) :-
    '$rosetta_call'(887, [ImageLoader, Index], Result).

%!  image_loader_take(+ImageLoader, +Indices:list(integer), -Result:image_batch) is det.
%
%   Reads the listed examples (split positions), in the order given.
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::take`.
%
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): if an index is not in [0, size()).
image_loader_take(ImageLoader, Indices, Result) :-
    '$rosetta_call'(888, [ImageLoader, Indices], Result).

%!  image_loader_load_all(+ImageLoader, -Result:image_batch) is det.
%
%   Reads every example of the epoch (all of size()) into one batch, in split order.
%   Mind memory: all 60000 MNIST images take ~376 MB as doubles; see set_limit().
%
%   Calls the C++ method `datamunge::datasets::ImageLoader::load_all`.
image_loader_load_all(ImageLoader, Result) :-
    '$rosetta_call'(889, [ImageLoader], Result).

% ---------------------------------------------------------------- mesh1_d
%
%   A 1D finite-element mesh: a strictly increasing sequence of node coordinates.
%   Element i spans [nodes[i], nodes[i+1]] for i in [0, num_elements()) -- no separate
%   connectivity array is needed since consecutive nodes are always the two endpoints
%   of one linear (P1) element. `nodes` is a public field for direct C++ construction,
%   but (matching datamunge::ode::ODESolution's t/y fields -- a swig-jse R-backend
%   codegen bug hits plain vector<double> struct *field* getters) is not exposed to
%   language bindings; node_at()/num_nodes() are the cross-language-safe accessors.
%
%   Wraps the C++ class `datamunge::fem::Mesh1D`.

%!  mesh1_d_new(-Object:mesh1_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::Mesh1D`.
mesh1_d_new(Object) :-
    '$rosetta_construct'(895, [], [], [], Object).

%!  mesh1_d_num_nodes(+Mesh1D, -Result:integer) is det.
%
%   Calls the C++ method `datamunge::fem::Mesh1D::num_nodes`.
mesh1_d_num_nodes(Mesh1D, Result) :-
    '$rosetta_call'(891, [Mesh1D], Result).

%!  mesh1_d_num_elements(+Mesh1D, -Result:integer) is det.
%
%   Calls the C++ method `datamunge::fem::Mesh1D::num_elements`.
mesh1_d_num_elements(Mesh1D, Result) :-
    '$rosetta_call'(892, [Mesh1D], Result).

%!  mesh1_d_node_at(+Mesh1D, +Index:integer, -Result:float) is det.
%
%   Calls the C++ method `datamunge::fem::Mesh1D::node_at`.
mesh1_d_node_at(Mesh1D, Index, Result) :-
    '$rosetta_call'(893, [Mesh1D, Index], Result).

%!  mesh1_d_element_length(+Mesh1D, +ElementIndex:integer, -Result:float) is det.
%
%   Calls the C++ method `datamunge::fem::Mesh1D::element_length`.
mesh1_d_element_length(Mesh1D, ElementIndex, Result) :-
    '$rosetta_call'(894, [Mesh1D, ElementIndex], Result).

% ---------------------------------------------------------------- scalar_field1_d
%
%   A user-supplied scalar source-term function of one spatial variable, f(x).
%   Director-enabled extension point (same pattern as datamunge::ode::RHS and
%   datamunge::optim::ArbitraryFunction elsewhere in this codebase): subclass and
%   override evaluate() in C++, or, via SWIG directors, in any binding with director
%   support. Bindings without director support must instead use
%   FEM1D::solve_builtin()'s fixed set of named source terms.
%
%   Wraps the C++ class `datamunge::fem::ScalarField1D`.
%
%   Abstract in C++: create an extended object (scalar_field1_d_extend) to implement its virtual methods in Prolog.

%!  scalar_field1_d_new(-Object:scalar_field1_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::ScalarField1D`.
scalar_field1_d_new(Object) :-
    '$rosetta_construct'(897, [], [], [], Object).

%!  scalar_field1_d_extend(+Module:atom, +Data, -Object:scalar_field1_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::ScalarField1D`.
%
%   Creates an extended object: a C++ subclass whose virtual methods run the clauses of `Module:override/1` for them (`override(area(Self, Area)) :- ...`), and the C++ implementation otherwise. Data is the object's data (object_data/2). Inside an override, calling the method's predicate on the object runs the C++ implementation.
scalar_field1_d_extend(Module, Data, Object) :-
    '$rosetta_construct'(897, [], Module, Data, Object).

%!  scalar_field1_d_evaluate(+ScalarField1D, +X:float, -Result:float) is det.
%
%   Calls the C++ method `datamunge::fem::ScalarField1D::evaluate`.
scalar_field1_d_evaluate(ScalarField1D, X, Result) :-
    '$rosetta_dispatch'(ScalarField1D, evaluate, [ScalarField1D, X, Result],
        '$rosetta_call'(896, [ScalarField1D, X], Result)).

% ---------------------------------------------------------------- scalar_field2_d
%
%   A user-supplied scalar source-term function of two spatial variables, f(x, y).
%   Same director-enabled pattern as ScalarField1D; FEM2D::solve_builtin() is the
%   fallback for bindings without director support.
%
%   Wraps the C++ class `datamunge::fem::ScalarField2D`.
%
%   Abstract in C++: create an extended object (scalar_field2_d_extend) to implement its virtual methods in Prolog.

%!  scalar_field2_d_new(-Object:scalar_field2_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::ScalarField2D`.
scalar_field2_d_new(Object) :-
    '$rosetta_construct'(899, [], [], [], Object).

%!  scalar_field2_d_extend(+Module:atom, +Data, -Object:scalar_field2_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::ScalarField2D`.
%
%   Creates an extended object: a C++ subclass whose virtual methods run the clauses of `Module:override/1` for them (`override(area(Self, Area)) :- ...`), and the C++ implementation otherwise. Data is the object's data (object_data/2). Inside an override, calling the method's predicate on the object runs the C++ implementation.
scalar_field2_d_extend(Module, Data, Object) :-
    '$rosetta_construct'(899, [], Module, Data, Object).

%!  scalar_field2_d_evaluate(+ScalarField2D, +X:float, +Y:float, -Result:float) is det.
%
%   Calls the C++ method `datamunge::fem::ScalarField2D::evaluate`.
scalar_field2_d_evaluate(ScalarField2D, X, Y, Result) :-
    '$rosetta_dispatch'(ScalarField2D, evaluate, [ScalarField2D, X, Y, Result],
        '$rosetta_call'(898, [ScalarField2D, X, Y], Result)).

% ---------------------------------------------------------------- boundary_condition1_d
%
%   Owned endpoint data for Dirichlet, outward-conormal Neumann or Robin conditions.
%   Dirichlet uses value as u; Neumann uses it as p*du/dn; Robin uses it as the
%   reference value in p*du/dn+alpha*(u-value)=0. Alpha zero gives zero conormal.
%   For coercive diffusion/heat models use nonnegative Robin alpha and sufficient
%   constraints/reaction to remove the constant nullspace. Unsupported enum values
%   and nonfinite data are outside the solver's preconditions, not fully validated.
%
%   Wraps the C++ class `datamunge::fem::BoundaryCondition1D`.
%
%   *Example*
%
%   ==
%   const dm::fem::BoundaryCondition1D right{dm::fem::BCType::Robin,4,3};
%   std::print("{} {}\n",right.value,right.robin_coefficient); // 4 3
%   ==

%!  boundary_condition1_d_new(-Object:boundary_condition1_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::BoundaryCondition1D`.
boundary_condition1_d_new(Object) :-
    '$rosetta_construct'(906, [], [], [], Object).

%!  boundary_condition1_d_type(+BoundaryCondition1D, -Value:bc_type) is det.
%
%   Supported condition kind; defaults to Dirichlet. (bc_type).
boundary_condition1_d_type(BoundaryCondition1D, Value) :-
    '$rosetta_call'(900, [BoundaryCondition1D], Value).

%!  boundary_condition1_d_set_type(+BoundaryCondition1D, +Value:bc_type) is det.
%
%   Sets boundary_condition1_d_type/2.
boundary_condition1_d_set_type(BoundaryCondition1D, Value) :-
    '$rosetta_call'(901, [BoundaryCondition1D, Value], _).

%!  boundary_condition1_d_value(+BoundaryCondition1D, -Value:float) is det.
%
%   Prescribed value, conormal or Robin reference, as selected by type. (float).
boundary_condition1_d_value(BoundaryCondition1D, Value) :-
    '$rosetta_call'(902, [BoundaryCondition1D], Value).

%!  boundary_condition1_d_set_value(+BoundaryCondition1D, +Value:float) is det.
%
%   Sets boundary_condition1_d_value/2.
boundary_condition1_d_set_value(BoundaryCondition1D, Value) :-
    '$rosetta_call'(903, [BoundaryCondition1D, Value], _).

%!  boundary_condition1_d_robin_coefficient(+BoundaryCondition1D, -Value:float) is det.
%
%   Robin alpha; ignored for other kinds. (float).
boundary_condition1_d_robin_coefficient(BoundaryCondition1D, Value) :-
    '$rosetta_call'(904, [BoundaryCondition1D], Value).

%!  boundary_condition1_d_set_robin_coefficient(+BoundaryCondition1D, +Value:float) is det.
%
%   Sets boundary_condition1_d_robin_coefficient/2.
boundary_condition1_d_set_robin_coefficient(BoundaryCondition1D, Value) :-
    '$rosetta_call'(905, [BoundaryCondition1D, Value], _).

% ---------------------------------------------------------------- fem1_d_result
%
%   Owned nodal P1 steady solution, with checked scalar accessors for language bindings.
%   The continuous finite-element field is the piecewise-linear interpolant of
%   these values; nodal agreement alone does not imply agreement between nodes.
%   Copies own their arrays, with no mesh/callback alias. Public edits can break
%   array consistency; accessors check the actual requested vector bounds.
%
%   Wraps the C++ class `datamunge::fem::FEM1DResult`.
%
%   *Example*
%
%   ==
%   const auto r=dm::fem::FEM1D::solve_builtin(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},"constant",{1},{},{});
%   std::print("{} {}\n",r.size(),r.value_at(1)); // 3 0.125
%   ==

%!  fem1_d_result_new(-Object:fem1_d_result) is det.
%
%   Calls the C++ constructor `datamunge::fem::FEM1DResult`.
fem1_d_result_new(Object) :-
    '$rosetta_construct'(910, [], [], [], Object).

%!  fem1_d_result_size(+Fem1DResult, -Result:integer) is det.
%
%   Count stored solution values without changing either array.
%
%   Calls the C++ method `datamunge::fem::FEM1DResult::size`.
%
%   @arg Result Actual u.size(); no allocation or shared mutation.
fem1_d_result_size(Fem1DResult, Result) :-
    '$rosetta_call'(907, [Fem1DResult], Result).

%!  fem1_d_result_node_at(+Fem1DResult, +Index:integer, -Result:float) is det.
%
%   Read an owned spatial coordinate with vector bounds checking.
%
%   Calls the C++ method `datamunge::fem::FEM1DResult::node_at`.
%
%   @arg Index Zero-based coordinate index.
%   @arg Result Stored coordinate by value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If index is outside nodes.
fem1_d_result_node_at(Fem1DResult, Index, Result) :-
    '$rosetta_call'(908, [Fem1DResult, Index], Result).

%!  fem1_d_result_value_at(+Fem1DResult, +Index:integer, -Result:float) is det.
%
%   Read an owned nodal value with vector bounds checking.
%
%   Calls the C++ method `datamunge::fem::FEM1DResult::value_at`.
%
%   @arg Index Zero-based value index.
%   @arg Result Stored solution value by value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If index is outside u.
fem1_d_result_value_at(Fem1DResult, Index, Result) :-
    '$rosetta_call'(909, [Fem1DResult, Index], Result).

% ---------------------------------------------------------------- fem1_d_time_series
%
%   Owned initial state and actual strictly advancing backward-Euler time slices.
%   Solver output has one u row per time and one value per spatial node. Initial
%   time zero/u0 are retained as supplied; later rows satisfy imposed boundary data.
%   Times retain rounded nominal-step products with a shortened final interval;
%   an already reached endpoint is not appended twice. Copies retain no mesh/source
%   alias. Public edits may break consistency; accessors check actual vector bounds.
%
%   Wraps the C++ class `datamunge::fem::FEM1DTimeSeries`.
%
%   *Example*
%
%   ==
%   const auto t=dm::fem::FEM1D::solve_transient_builtin(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},"constant",{1},{},{},{0,0,0},.5,.5);
%   std::print("{} {:.6f}\n",t.num_steps(),t.value_at(1,1)); // 2 0.107143
%   ==

%!  fem1_d_time_series_new(-Object:fem1_d_time_series) is det.
%
%   Calls the C++ constructor `datamunge::fem::FEM1DTimeSeries`.
fem1_d_time_series_new(Object) :-
    '$rosetta_construct'(916, [], [], [], Object).

%!  fem1_d_time_series_num_steps(+Fem1DTimeSeries, -Result:integer) is det.
%
%   Count stored time levels, including the initial state.
%
%   Calls the C++ method `datamunge::fem::FEM1DTimeSeries::num_steps`.
%
%   @arg Result Actual times.size(), rather than the number of time advances.
fem1_d_time_series_num_steps(Fem1DTimeSeries, Result) :-
    '$rosetta_call'(911, [Fem1DTimeSeries], Result).

%!  fem1_d_time_series_num_nodes(+Fem1DTimeSeries, -Result:integer) is det.
%
%   Count stored spatial coordinates.
%
%   Calls the C++ method `datamunge::fem::FEM1DTimeSeries::num_nodes`.
%
%   @arg Result Actual nodes.size(); no allocation or shared mutation.
fem1_d_time_series_num_nodes(Fem1DTimeSeries, Result) :-
    '$rosetta_call'(912, [Fem1DTimeSeries], Result).

%!  fem1_d_time_series_node_at(+Fem1DTimeSeries, +Index:integer, -Result:float) is det.
%
%   Read a spatial coordinate with vector bounds checking.
%
%   Calls the C++ method `datamunge::fem::FEM1DTimeSeries::node_at`.
%
%   @arg Index Zero-based coordinate index.
%   @arg Result Owned coordinate by value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If index is outside nodes.
fem1_d_time_series_node_at(Fem1DTimeSeries, Index, Result) :-
    '$rosetta_call'(913, [Fem1DTimeSeries, Index], Result).

%!  fem1_d_time_series_time_at(+Fem1DTimeSeries, +Step:integer, -Result:float) is det.
%
%   Read an actual stored time level with bounds checking.
%
%   Calls the C++ method `datamunge::fem::FEM1DTimeSeries::time_at`.
%
%   @arg Step Zero-based frame index, including initial frame zero.
%   @arg Result Actual stored time by value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If step is outside times.
fem1_d_time_series_time_at(Fem1DTimeSeries, Step, Result) :-
    '$rosetta_call'(914, [Fem1DTimeSeries, Step], Result).

%!  fem1_d_time_series_value_at(+Fem1DTimeSeries, +Step:integer, +NodeIndex:integer, -Result:float) is det.
%
%   Read a stored nodal time-slice value with both vector bounds checked.
%
%   Calls the C++ method `datamunge::fem::FEM1DTimeSeries::value_at`.
%
%   @arg Step Zero-based time-frame index in u.
%   @arg NodeIndex Zero-based spatial index within that row.
%   @arg Result Stored nodal value by value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If either index is outside the actual stored vectors.
fem1_d_time_series_value_at(Fem1DTimeSeries, Step, NodeIndex, Result) :-
    '$rosetta_call'(915, [Fem1DTimeSeries, Step, NodeIndex], Result).

% ---------------------------------------------------------------- fem1_d
%
%   Solve steady or transient one-dimensional divergence-form problems with P1 Galerkin FEM.
%   Models -(p*u')'+q*u=f and u_t-(p*u')'+q*u=f on a caller-supplied mesh.
%   Requires at least two finite strictly increasing nodes, finite coefficient/
%   boundary/source data and finite assembled arithmetic with nonzero Thomas pivots;
%   those mathematical/geometry preconditions are not fully validated. Positive p,
%   nonnegative q/Robin data and adequate constraints give the usual coercive model.
%   Piecewise-constant p/q can be scalar or one per element. Results own their
%   values; input mesh/data are unchanged. Calls share no mutable global state,
%   while callback side effects/concurrency belong to the caller.
%
%   Wraps the C++ class `datamunge::fem::FEM1D`.
%
%   *Example*
%
%   ==
%   const auto r=dm::fem::FEM1D::solve_builtin(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},"constant",{1},{},{});
%   std::print("{}\n",r.value_at(1)); // 0.125
%   ==
%
%   *References*
%
%     - MFEM, Weak Formulations: https://mfem.org/fem_weak_form/ . This native implementation
%       uses P1 intervals, three-point Gauss-Legendre loads and a tridiagonal direct solve.

%!  fem1_d_new(-Object:fem1_d) is det.
%
%   Calls the C++ constructor `datamunge::fem::FEM1D`.
fem1_d_new(Object) :-
    '$rosetta_construct'(921, [], [], [], Object).

%!  fem1_d_solve(+Mesh:mesh1_d, +P:list(float), +Q:list(float), +F:scalar_field1_d, +Left:boundary_condition1_d, +Right:boundary_condition1_d, -Result:fem1_d_result) is det.
%
%   Solve the steady P1 system for -(p*u')'+q*u=f with endpoint boundary data.
%   Follows FEM1D's mesh/coefficient/finite-arithmetic/nonsingular-pivot preconditions.
%   Uses three-point Gauss-Legendre quadrature of f times each local basis, natural
%   boundary terms and symmetric Dirichlet elimination, then Thomas elimination.
%   O(N) work/storage for N nodes; invokes the source three times per element.
%   No callback pointer is retained. Independent calls share no mutable state.
%
%   Calls the C++ method `datamunge::fem::FEM1D::solve`.
%
%   *Example*
%
%   ==
%   struct Unit final:dm::fem::ScalarField1D{double evaluate(double) override{return 1;}} source;
%   const auto r=dm::fem::FEM1D::solve(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},source,{},{});
%   std::print("{}\n",r.value_at(1)); // 0.125
%   ==
%
%   *References*
%
%     - https://mfem.org/fem_weak_form/ ; native interval P1 and quadrature choices as FEM1D.
%
%   @arg Mesh Borrowed mesh with at least two finite strictly increasing nodes.
%   @arg P Borrowed diffusion coefficient: length1 or one per element.
%   @arg Q Borrowed reaction coefficient: length1 or one per element.
%   @arg F Borrowed spatial source; evaluate() may have caller-owned side effects.
%   @arg Left Left endpoint condition, with outward normal -1.
%   @arg Right Right endpoint condition, with outward normal +1.
%   @arg Result Owned original nodes and computed nodal values.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If p/q are empty or have the wrong lengths.
%   @throws error(native_error(native, Message), _) (C++ `std::bad_alloc`): If assembly/result storage cannot be allocated; callback exceptions propagate.
%   @see `solve_builtin()`, `solve_transient()`
fem1_d_solve(Mesh, P, Q, F, Left, Right, Result) :-
    '$rosetta_call'(917, [Mesh, P, Q, F, Left, Right], Result).

%!  fem1_d_solve_builtin(+Mesh:mesh1_d, +P:list(float), +Q:list(float), +Source:string, +SourceParams:list(float), +Left:boundary_condition1_d, +Right:boundary_condition1_d, -Result:fem1_d_result) is det.
%
%   Solve the steady system using an owned named spatial source, without a director callback.
%   Shares the live-source solver and its mathematical/precondition/storage contracts.
%   Sources: zero=0 (params unused); constant=c ({1}); linear=m*x+c ({1,0});
%   polynomial=sum(params[i]*x^i) (empty gives0); sine=A*sin(w*x+phase) ({1,1,0}).
%   Missing trailing parameters use those defaults; extra parameters are ignored
%   except polynomial, which uses all entries. Name matching is exact/case-sensitive.
%
%   Calls the C++ method `datamunge::fem::FEM1D::solve_builtin`.
%
%   *Example*
%
%   ==
%   const auto r=dm::fem::FEM1D::solve_builtin(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},"constant",{}, {},{});
%   std::print("{}\n",r.value_at(1)); // 0.125
%   ==
%
%   *References*
%
%     - https://mfem.org/fem_weak_form/ ; source definitions are native convenience choices.
%
%   @arg Mesh Borrowed valid finite interval mesh; unchanged.
%   @arg P Borrowed scalar/per-element diffusion coefficient.
%   @arg Q Borrowed scalar/per-element reaction coefficient.
%   @arg Source Exact name zero, constant, linear, polynomial or sine.
%   @arg SourceParams Borrowed positional source parameters, with defaults described above.
%   @arg Left Left endpoint data using outward normal -1.
%   @arg Right Right endpoint data using outward normal +1.
%   @arg Result Owned computed nodal result, retaining no source or input reference.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For an unknown source or malformed p/q lengths.
%   @throws error(native_error(native, Message), _) (C++ `std::bad_alloc`): If owned parameter/assembly/result storage cannot be allocated.
%   @see `solve()`, `solve_transient_builtin()`
fem1_d_solve_builtin(Mesh, P, Q, Source, SourceParams, Left, Right, Result) :-
    '$rosetta_call'(918, [Mesh, P, Q, Source, SourceParams, Left, Right], Result).

%!  fem1_d_solve_transient(+Mesh:mesh1_d, +P:list(float), +Q:list(float), +F:scalar_field1_d, +Left:boundary_condition1_d, +Right:boundary_condition1_d, +U0:list(float), +TEnd:float, +Dt:float, -Result:fem1_d_time_series) is det.
%
%   Integrate u_t-(p*u')'+q*u=f with P1 space and actual backward-Euler time intervals.
%   Shares FEM1D's spatial/finite-arithmetic/nonzero-pivot preconditions. Source
%   and boundary data represent a time-independent model; the live callback is
%   actually reevaluated three times per element at every time advance, not cached.
%   Stores initial u0 as supplied, then imposes boundary data at later solves.
%   Nominal step dt is shortened at t_end; actual positive time differences enter
%   the mass term. Stops once t_end is reached, avoiding a duplicate rounded last
%   time even when ceil(t_end/dt) overestimates the number of advances.
%   O(S*N) work/output storage for S advances/N nodes, O(N) assembly temporaries;
%   no optional trace or quota. Backward Euler is unconditionally stable for the
%   coercive semidiscrete model, not a guarantee of arbitrary-step accuracy or
%   finite arithmetic for arbitrary parameters. Input arrays remain unchanged;
%   callback exceptions/side effects/concurrent safety belong to caller.
%
%   Calls the C++ method `datamunge::fem::FEM1D::solve_transient`.
%
%   *Example*
%
%   ==
%   struct Zero final:dm::fem::ScalarField1D{double evaluate(double) override{return 0;}} source;
%   const auto t=dm::fem::FEM1D::solve_transient(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},source,{},{},{0,1,0},.5,.5);
%   std::print("{} {:.6f}\n",t.num_steps(),t.value_at(1,1)); // 2 0.142857
%   ==
%
%   *References*
%
%     - Arnold (2012), Numerical Analysis of Partial Differential Equations, chapter5 section2.
%       https://www-users.cse.umn.edu/~arnold/8445.f12/notes.pdf . Native load quadrature,
%       fixed data and rounded/shortened time grid are implementation choices.
%
%   @arg Mesh Borrowed valid mesh with at least two finite increasing nodes.
%   @arg P Borrowed scalar/per-element diffusion coefficient.
%   @arg Q Borrowed scalar/per-element reaction coefficient.
%   @arg F Borrowed spatial callback, reevaluated at every advance.
%   @arg Left Fixed left condition, with outward normal -1.
%   @arg Right Fixed right condition, with outward normal +1.
%   @arg U0 Borrowed finite initial nodal values, exactly one per mesh node.
%   @arg TEnd Positive finite final time, in time units.
%   @arg Dt Positive finite nominal time step in the same units; may exceed t_end.
%   @arg Result Owned nodes, initial state and strictly advancing slices ending at t_end.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For fewer than two nodes, wrong coefficient/u0 lengths or nonpositive/nonfinite time controls.
%   @throws error(native_error(length_error, Message), _) (C++ `std::length_error`): If frame counts, vector capacities or total scalar count cannot be represented.
%   @throws error(native_error(arithmetic_error, Message), _) (C++ `std::overflow_error`): If rounded time products cannot advance before t_end.
%   @throws error(native_error(native, Message), _) (C++ `std::bad_alloc`): If output/assembly storage cannot be allocated; callback exceptions propagate.
%   @see `solve_transient_builtin()`, fem1_d_time_series_new/1
fem1_d_solve_transient(Mesh, P, Q, F, Left, Right, U0, TEnd, Dt, Result) :-
    '$rosetta_call'(919, [Mesh, P, Q, F, Left, Right, U0, TEnd, Dt], Result).

%!  fem1_d_solve_transient_builtin(+Mesh:mesh1_d, +P:list(float), +Q:list(float), +Source:string, +SourceParams:list(float), +Left:boundary_condition1_d, +Right:boundary_condition1_d, +U0:list(float), +TEnd:float, +Dt:float, -Result:fem1_d_time_series) is det.
%
%   Integrate the same backward-Euler model with a named source and no callback subclass.
%   Uses the same private source construction as solve_builtin() and the same
%   actual time loop as solve_transient(); no second solver or per-language glue.
%   Names/defaults: zero=0; constant=c ({1}); linear=m*x+c ({1,0});
%   polynomial=sum(params[i]*x^i) (empty0); sine=A*sin(w*x+phase) ({1,1,0}).
%   Extra entries ignored except polynomial; exact case-sensitive names. Source
%   objects are local and synchronous; results own values, not callback aliases.
%   All spatial/time/initial-state, complexity and stability contracts follow
%   solve_transient(); ordinary output has no optional history/quota.
%
%   Calls the C++ method `datamunge::fem::FEM1D::solve_transient_builtin`.
%
%   *Example*
%
%   ==
%   const auto t=dm::fem::FEM1D::solve_transient_builtin(dm::fem::make_uniform_mesh1d(0,1,2),{1},{0},"constant",{1},{},{},{0,0,0},.5,.5);
%   std::print("{} {:.6f}\n",t.num_steps(),t.value_at(1,1)); // 2 0.107143
%   ==
%
%   *References*
%
%     - https://www-users.cse.umn.edu/~arnold/8445.f12/notes.pdf ; same native discretization as solve_transient().
%
%   @arg Mesh Borrowed valid finite increasing mesh, with at least two nodes.
%   @arg P Borrowed scalar/per-element diffusion coefficient.
%   @arg Q Borrowed scalar/per-element reaction coefficient.
%   @arg Source Exact name zero, constant, linear, polynomial or sine.
%   @arg SourceParams Borrowed positional parameters; omitted trailing values use the defaults above.
%   @arg Left Fixed left boundary condition using outward normal -1.
%   @arg Right Fixed right boundary condition using outward normal +1.
%   @arg U0 Borrowed finite initial values, exactly one per spatial node.
%   @arg TEnd Positive finite final time.
%   @arg Dt Positive finite nominal time step; final interval is shortened as needed.
%   @arg Result Owned initial state and actual strictly advancing backward-Euler slices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): For an unknown source, malformed coefficient/u0 lengths, fewer than two nodes or nonpositive/nonfinite time controls.
%   @throws error(native_error(length_error, Message), _) (C++ `std::length_error`): If frame/container/total scalar counts cannot be represented.
%   @throws error(native_error(arithmetic_error, Message), _) (C++ `std::overflow_error`): If rounded time products cannot advance.
%   @throws error(native_error(native, Message), _) (C++ `std::bad_alloc`): If parameters, output or assembly storage cannot be allocated.
%   @see `solve_builtin()`, `solve_transient()`
fem1_d_solve_transient_builtin(Mesh, P, Q, Source, SourceParams, Left, Right, U0, TEnd, Dt, Result) :-
    '$rosetta_call'(920, [Mesh, P, Q, Source, SourceParams, Left, Right, U0, TEnd, Dt], Result).

% ---------------------------------------------------------------- point2_d
%
%   A copied point or free vector with ordinary double coordinates.
%   Construction does not validate finiteness; checked algorithms document their
%   own input contracts. Default coordinates are zero. Equality is numeric, so
%   signed zeros compare equal and NaN coordinates do not compare equal.
%
%   Wraps the C++ class `datamunge::geometry::Point2D`.
%
%   *Example*
%
%   ==
%   const dm::geometry::Point2D p{3,4};
%   std::cout << p.x << ' ' << p.y; // 3 4
%   ==

%!  point2_d_new(-Object:point2_d) is det.
%
%   Calls the C++ constructor `datamunge::geometry::Point2D`.
point2_d_new(Object) :-
    '$rosetta_construct'(928, [], [], [], Object).

%!  point2_d_equals(+Point2D, +Other:point2_d, -Result:boolean) is det.
%
%   Compare both coordinates with ordinary double equality.
%
%   Calls the C++ operator `datamunge::geometry::Point2D::operator==`.
%
%   *Example*
%
%   ==
%   std::cout << (dm::geometry::Point2D{0,1}==dm::geometry::Point2D{-0.,1}); // 1
%   ==
%
%   @arg Other Point to compare without mutation.
%   @arg Result Both coordinate comparisons are true; signed zeros compare equal.
%   @see `operator!=()`
point2_d_equals(Point2D, Other, Result) :-
    '$rosetta_call'(922, [Point2D, Other], Result).

%!  point2_d_not_equals(+Point2D, +Other:point2_d, -Result:boolean) is det.
%
%   Negate coordinate equality, including unequal NaN coordinates.
%
%   Calls the C++ operator `datamunge::geometry::Point2D::operator!=`.
%
%   *Example*
%
%   ==
%   std::cout << (dm::geometry::Point2D{0,1}!=dm::geometry::Point2D{0,2}); // 1
%   ==
%
%   @arg Other Point to compare without mutation.
%   @arg Result Logical negation of operator==().
%   @see `operator==()`
point2_d_not_equals(Point2D, Other, Result) :-
    '$rosetta_call'(923, [Point2D, Other], Result).

%!  point2_d_x(+Point2D, -Value:float) is det.
%
%   Horizontal coordinate, default zero. (float).
point2_d_x(Point2D, Value) :-
    '$rosetta_call'(924, [Point2D], Value).

%!  point2_d_set_x(+Point2D, +Value:float) is det.
%
%   Sets point2_d_x/2.
point2_d_set_x(Point2D, Value) :-
    '$rosetta_call'(925, [Point2D, Value], _).

%!  point2_d_y(+Point2D, -Value:float) is det.
%
%   Vertical coordinate, default zero. (float).
point2_d_y(Point2D, Value) :-
    '$rosetta_call'(926, [Point2D], Value).

%!  point2_d_set_y(+Point2D, +Value:float) is det.
%
%   Sets point2_d_y/2.
point2_d_set_y(Point2D, Value) :-
    '$rosetta_call'(927, [Point2D, Value], _).

% ---------------------------------------------------------------- triangle
%
%   Three original point indices in counterclockwise order for finite mesh faces.
%   Original field layout/defaults are retained. A trace ghost uses c=points.size()
%   as a symbolic infinity marker, with a,b the reversed finite hull edge; it is
%   never returned by delaunay_triangulation(). No coordinate is constructed for it.
%
%   Wraps the C++ class `datamunge::geometry::Triangle`.
%
%   *Example*
%
%   ==
%   const dm::geometry::Triangle t{0,1,2};std::print("{} {} {}\n",t.a,t.b,t.c); // 0 1 2
%   ==

%!  triangle_new(-Object:triangle) is det.
%
%   Calls the C++ constructor `datamunge::geometry::Triangle`.
triangle_new(Object) :-
    '$rosetta_construct'(935, [], [], [], Object).

%!  triangle_a(+Triangle, -Value:integer) is det.
%
%   First original index, finite also for a trace ghost. (integer).
triangle_a(Triangle, Value) :-
    '$rosetta_call'(929, [Triangle], Value).

%!  triangle_set_a(+Triangle, +Value:integer) is det.
%
%   Sets triangle_a/2.
triangle_set_a(Triangle, Value) :-
    '$rosetta_call'(930, [Triangle, Value], _).

%!  triangle_b(+Triangle, -Value:integer) is det.
%
%   Second original index, finite also for a trace ghost. (integer).
triangle_b(Triangle, Value) :-
    '$rosetta_call'(931, [Triangle], Value).

%!  triangle_set_b(+Triangle, +Value:integer) is det.
%
%   Sets triangle_b/2.
triangle_set_b(Triangle, Value) :-
    '$rosetta_call'(932, [Triangle, Value], _).

%!  triangle_c(+Triangle, -Value:integer) is det.
%
%   Third original index; points.size() denotes a trace ghost only. (integer).
triangle_c(Triangle, Value) :-
    '$rosetta_call'(933, [Triangle], Value).

%!  triangle_set_c(+Triangle, +Value:integer) is det.
%
%   Sets triangle_c/2.
triangle_set_c(Triangle, Value) :-
    '$rosetta_call'(934, [Triangle, Value], _).

% ---------------------------------------------------------------- delaunay_work
%
%   Actual seed and cavity operations, excluding validation, sorting and copies.
%   A conflict test is either an incircle test on a finite face or an exact
%   half-plane test on a ghost. Counters exclude CCW checks on newly created faces,
%   between-endpoint comparisons, map operations, allocation, trace copies and final
%   sorting. Initial seed plus three ghosts are excluded from creation/removal counts.
%   No counts are estimates of time or fixed-predicate internal arithmetic.
%
%   Wraps the C++ class `datamunge::geometry::DelaunayWork`.
%
%   *Example*
%
%   ==
%   const auto t=dm::geometry::delaunay_trace({{0,0},{4,0},{4,4},{0,4},{2,2}});
%   std::print("{} {}\n",t.work.insertions,t.work.incircle_tests+t.work.hull_side_tests); // 2 10
%   ==

%!  delaunay_work_new(-Object:delaunay_work) is det.
%
%   Calls the C++ constructor `datamunge::geometry::DelaunayWork`.
delaunay_work_new(Object) :-
    '$rosetta_construct'(950, [], [], [], Object).

%!  delaunay_work_seed_orientation_tests(+DelaunayWork, -Value:integer) is det.
%
%   Exact tests finding the first noncollinear seed. (integer).
delaunay_work_seed_orientation_tests(DelaunayWork, Value) :-
    '$rosetta_call'(936, [DelaunayWork], Value).

%!  delaunay_work_set_seed_orientation_tests(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_seed_orientation_tests/2.
delaunay_work_set_seed_orientation_tests(DelaunayWork, Value) :-
    '$rosetta_call'(937, [DelaunayWork, Value], _).

%!  delaunay_work_insertions(+DelaunayWork, -Value:integer) is det.
%
%   Actual non-seed distinct sites inserted. (integer).
delaunay_work_insertions(DelaunayWork, Value) :-
    '$rosetta_call'(938, [DelaunayWork], Value).

%!  delaunay_work_set_insertions(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_insertions/2.
delaunay_work_set_insertions(DelaunayWork, Value) :-
    '$rosetta_call'(939, [DelaunayWork, Value], _).

%!  delaunay_work_incircle_tests(+DelaunayWork, -Value:integer) is det.
%
%   Finite live faces tested against an inserted site. (integer).
delaunay_work_incircle_tests(DelaunayWork, Value) :-
    '$rosetta_call'(940, [DelaunayWork], Value).

%!  delaunay_work_set_incircle_tests(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_incircle_tests/2.
delaunay_work_set_incircle_tests(DelaunayWork, Value) :-
    '$rosetta_call'(941, [DelaunayWork, Value], _).

%!  delaunay_work_hull_side_tests(+DelaunayWork, -Value:integer) is det.
%
%   Symbolic boundary faces tested by orientation. (integer).
delaunay_work_hull_side_tests(DelaunayWork, Value) :-
    '$rosetta_call'(942, [DelaunayWork], Value).

%!  delaunay_work_set_hull_side_tests(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_hull_side_tests/2.
delaunay_work_set_hull_side_tests(DelaunayWork, Value) :-
    '$rosetta_call'(943, [DelaunayWork, Value], _).

%!  delaunay_work_removed_faces(+DelaunayWork, -Value:integer) is det.
%
%   All conflicting real/ghost faces removed. (integer).
delaunay_work_removed_faces(DelaunayWork, Value) :-
    '$rosetta_call'(944, [DelaunayWork], Value).

%!  delaunay_work_set_removed_faces(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_removed_faces/2.
delaunay_work_set_removed_faces(DelaunayWork, Value) :-
    '$rosetta_call'(945, [DelaunayWork, Value], _).

%!  delaunay_work_boundary_edges(+DelaunayWork, -Value:integer) is det.
%
%   Actual directed cavity edges retained once. (integer).
delaunay_work_boundary_edges(DelaunayWork, Value) :-
    '$rosetta_call'(946, [DelaunayWork], Value).

%!  delaunay_work_set_boundary_edges(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_boundary_edges/2.
delaunay_work_set_boundary_edges(DelaunayWork, Value) :-
    '$rosetta_call'(947, [DelaunayWork, Value], _).

%!  delaunay_work_created_faces(+DelaunayWork, -Value:integer) is det.
%
%   New real/ghost faces, one per boundary edge. (integer).
delaunay_work_created_faces(DelaunayWork, Value) :-
    '$rosetta_call'(948, [DelaunayWork], Value).

%!  delaunay_work_set_created_faces(+DelaunayWork, +Value:integer) is det.
%
%   Sets delaunay_work_created_faces/2.
delaunay_work_set_created_faces(DelaunayWork, Value) :-
    '$rosetta_call'(949, [DelaunayWork, Value], _).

% ---------------------------------------------------------------- delaunay_insertion
%
%   Owned actual cavity removal, directed boundary and replacement for one site.
%   removed/added may contain ghosts, identified by c=the original input count.
%   boundary is ordered by canonical undirected endpoint key but retains the first
%   directed occurrence; shared interior edges are cancelled. Actual face scans
%   precede this event. No full before/after mesh snapshot or geometric replay is
%   retained. All vectors own their entries and have no input lifetime dependency.
%
%   Wraps the C++ class `datamunge::geometry::DelaunayInsertion`.
%
%   *Example*
%
%   ==
%   const auto t=dm::geometry::delaunay_trace({{0,0},{4,0},{4,4},{0,4},{2,2}});
%   std::print("{} {} {}\n",t.steps.back().input_index,t.steps.back().removed.size(),t.steps.back().added.size()); // 4 2 4
%   ==

%!  delaunay_insertion_new(-Object:delaunay_insertion) is det.
%
%   Calls the C++ constructor `datamunge::geometry::DelaunayInsertion`.
delaunay_insertion_new(Object) :-
    '$rosetta_construct'(963, [], [], [], Object).

%!  delaunay_insertion_input_index(+DelaunayInsertion, -Value:integer) is det.
%
%   Earliest original id of the inserted distinct coordinate. (integer).
delaunay_insertion_input_index(DelaunayInsertion, Value) :-
    '$rosetta_call'(951, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_input_index(+DelaunayInsertion, +Value:integer) is det.
%
%   Sets delaunay_insertion_input_index/2.
delaunay_insertion_set_input_index(DelaunayInsertion, Value) :-
    '$rosetta_call'(952, [DelaunayInsertion, Value], _).

%!  delaunay_insertion_faces_before(+DelaunayInsertion, -Value:integer) is det.
%
%   Live real plus ghost faces before this insertion. (integer).
delaunay_insertion_faces_before(DelaunayInsertion, Value) :-
    '$rosetta_call'(953, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_faces_before(+DelaunayInsertion, +Value:integer) is det.
%
%   Sets delaunay_insertion_faces_before/2.
delaunay_insertion_set_faces_before(DelaunayInsertion, Value) :-
    '$rosetta_call'(954, [DelaunayInsertion, Value], _).

%!  delaunay_insertion_faces_after(+DelaunayInsertion, -Value:integer) is det.
%
%   Live real plus ghost faces after this insertion. (integer).
delaunay_insertion_faces_after(DelaunayInsertion, Value) :-
    '$rosetta_call'(955, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_faces_after(+DelaunayInsertion, +Value:integer) is det.
%
%   Sets delaunay_insertion_faces_after/2.
delaunay_insertion_set_faces_after(DelaunayInsertion, Value) :-
    '$rosetta_call'(956, [DelaunayInsertion, Value], _).

%!  delaunay_insertion_removed(+DelaunayInsertion, -Value:list(triangle)) is det.
%
%   Exact actual conflicting faces, in scan order. (list(triangle)).
delaunay_insertion_removed(DelaunayInsertion, Value) :-
    '$rosetta_call'(957, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_removed(+DelaunayInsertion, +Value:list(triangle)) is det.
%
%   Sets delaunay_insertion_removed/2.
delaunay_insertion_set_removed(DelaunayInsertion, Value) :-
    '$rosetta_call'(958, [DelaunayInsertion, Value], _).

%!  delaunay_insertion_boundary(+DelaunayInsertion, -Value:list(pair(integer, integer))) is det.
%
%   Actual directed nonshared cavity edges. (list(pair(integer, integer))).
delaunay_insertion_boundary(DelaunayInsertion, Value) :-
    '$rosetta_call'(959, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_boundary(+DelaunayInsertion, +Value:list(pair(integer, integer))) is det.
%
%   Sets delaunay_insertion_boundary/2.
delaunay_insertion_set_boundary(DelaunayInsertion, Value) :-
    '$rosetta_call'(960, [DelaunayInsertion, Value], _).

%!  delaunay_insertion_added(+DelaunayInsertion, -Value:list(triangle)) is det.
%
%   Actual replacement real/ghost faces, in boundary-key order. (list(triangle)).
delaunay_insertion_added(DelaunayInsertion, Value) :-
    '$rosetta_call'(961, [DelaunayInsertion], Value).

%!  delaunay_insertion_set_added(+DelaunayInsertion, +Value:list(triangle)) is det.
%
%   Sets delaunay_insertion_added/2.
delaunay_insertion_set_added(DelaunayInsertion, Value) :-
    '$rosetta_call'(962, [DelaunayInsertion, Value], _).

% ---------------------------------------------------------------- delaunay_trace
%
%   Complete owned sites, earliest-identity mapping, finite mesh and actual events.
%   Numeric coordinate equality coalesces duplicates and signed zeros. Representatives
%   retain earliest input indices in input order. Seed is the first two distinct
%   sites and first later noncollinear site; remaining distinct sites are inserted
%   in input order. Strict positive incircle conflicts retain an existing diagonal
%   on an exact cocircular tie; permutations may therefore select another valid mesh.
%   Final finite triangles rotate their smallest id first and are lexicographically
%   sorted, independent of map/hash traversal. All-collinear/fewer than three
%   distinct sites have no seed, faces or insertion events. All fields own data;
%   public edits are unchecked and independent calls share no mutable state.
%
%   Wraps the C++ class `datamunge::geometry::DelaunayTrace`.
%
%   *Example*
%
%   ==
%   const auto t=dm::geometry::delaunay_trace({{0,0},{1,0},{0,1},{0,0}});
%   std::print("{} {} {}\n",t.representatives.size(),t.representative_for_input.back(),t.triangles.size()); // 3 0 1
%   ==

%!  delaunay_trace_new(-Object:delaunay_trace) is det.
%
%   Calls the C++ constructor `datamunge::geometry::DelaunayTrace`.
delaunay_trace_new(Object) :-
    '$rosetta_construct'(980, [], [], [], Object).

%!  delaunay_trace_points(+DelaunayTrace, -Value:list(point2_d)) is det.
%
%   Complete copied original coordinates, including duplicates. (list(point2_d)).
delaunay_trace_points(DelaunayTrace, Value) :-
    '$rosetta_call'(964, [DelaunayTrace], Value).

%!  delaunay_trace_set_points(+DelaunayTrace, +Value:list(point2_d)) is det.
%
%   Sets delaunay_trace_points/2.
delaunay_trace_set_points(DelaunayTrace, Value) :-
    '$rosetta_call'(965, [DelaunayTrace, Value], _).

%!  delaunay_trace_representatives(+DelaunayTrace, -Value:list(integer)) is det.
%
%   Earliest unique ids in original input order. (list(integer)).
delaunay_trace_representatives(DelaunayTrace, Value) :-
    '$rosetta_call'(966, [DelaunayTrace], Value).

%!  delaunay_trace_set_representatives(+DelaunayTrace, +Value:list(integer)) is det.
%
%   Sets delaunay_trace_representatives/2.
