%   Sets delaunay_analysis_triangles/2.
delaunay_analysis_set_triangles(DelaunayAnalysis, Value) :-
    '$rosetta_call'(986, [DelaunayAnalysis, Value], _).

%!  delaunay_analysis_edges(+DelaunayAnalysis, -Value:integer) is det.
%
%   Distinct undirected coordinate edges. (integer).
delaunay_analysis_edges(DelaunayAnalysis, Value) :-
    '$rosetta_call'(987, [DelaunayAnalysis], Value).

%!  delaunay_analysis_set_edges(+DelaunayAnalysis, +Value:integer) is det.
%
%   Sets delaunay_analysis_edges/2.
delaunay_analysis_set_edges(DelaunayAnalysis, Value) :-
