%!  estimation_of_distribution_options_selection_ratio(+EstimationOfDistributionOptions, -Value:float) is det.
%
%   Fraction of population_size kept as "elite" each generation to re-estimate the Gaussian from; mu = max(2, ceil(population_size * selection_ratio)). (float).
estimation_of_distribution_options_selection_ratio(EstimationOfDistributionOptions, Value) :-
    '$rosetta_call'(1719, [EstimationOfDistributionOptions], Value).

%!  estimation_of_distribution_options_set_selection_ratio(+EstimationOfDistributionOptions, +Value:float) is det.
%
%   Sets estimation_of_distribution_options_selection_ratio/2.
estimation_of_distribution_options_set_selection_ratio(EstimationOfDistributionOptions, Value) :-
    '$rosetta_call'(1720, [EstimationOfDistributionOptions, Value], _).

%!  estimation_of_distribution_options_initial_std_dev(+EstimationOfDistributionOptions, -Value:float) is det.
%
%   Per-dimension standard deviation of the initial diagonal covariance. (float).
estimation_of_distribution_options_initial_std_dev(EstimationOfDistributionOptions, Value) :-
    '$rosetta_call'(1721, [EstimationOfDistributionOptions], Value).

%!  estimation_of_distribution_options_set_initial_std_dev(+EstimationOfDistributionOptions, +Value:float) is det.
%
%   Sets estimation_of_distribution_options_initial_std_dev/2.
estimation_of_distribution_options_set_initial_std_dev(EstimationOfDistributionOptions, Value) :-
    '$rosetta_call'(1722, [EstimationOfDistributionOptions, Value], _).

%!  estimation_of_distribution_options_covariance_regularization(+EstimationOfDistributionOptions, -Value:float) is det.
%
%   Diagonal regularization added to the re-estimated covariance every generation, to keep it numerically well-conditioned (needed whenever mu <= dimension, or whenever the elite set happens to be nearly coplanar). (float).
estimation_of_distribution_options_covariance_regularization(EstimationOfDistributionOptions, Value) :-
    '$rosetta_call'(1723, [EstimationOfDistributionOptions], Value).

%!  estimation_of_distribution_options_set_covariance_regularization(+EstimationOfDistributionOptions, +Value:float) is det.
%
%   Sets estimation_of_distribution_options_covariance_regularization/2.
estimation_of_distribution_options_set_covariance_regularization(EstimationOfDistributionOptions, Value) :-
