interior_point_options_set_initial_barrier(InteriorPointOptions, Value) :-
    '$rosetta_call'(1858, [InteriorPointOptions, Value], _).

%!  interior_point_options_barrier_decay(+InteriorPointOptions, -Value:float) is det.
%
%   Barrier multiplier after each inner budget. Default 0.1. (float).
interior_point_options_barrier_decay(InteriorPointOptions, Value) :-
    '$rosetta_call'(1859, [InteriorPointOptions], Value).

%!  interior_point_options_set_barrier_decay(+InteriorPointOptions, +Value:float) is det.
%
%   Sets interior_point_options_barrier_decay/2.
interior_point_options_set_barrier_decay(InteriorPointOptions, Value) :-
    '$rosetta_call'(1860, [InteriorPointOptions, Value], _).

%!  interior_point_options_max_outer_iterations(+InteriorPointOptions, -Value:integer) is det.
%
%   Maximum multiplier/barrier outer stages. Default 20. (integer).
interior_point_options_max_outer_iterations(InteriorPointOptions, Value) :-
    '$rosetta_call'(1861, [InteriorPointOptions], Value).

%!  interior_point_options_set_max_outer_iterations(+InteriorPointOptions, +Value:integer) is det.
%
