%   Sets gaussian_process_surrogate_options_exploration/2.
gaussian_process_surrogate_options_set_exploration(GaussianProcessSurrogateOptions, Value) :-
    '$rosetta_call'(1898, [GaussianProcessSurrogateOptions, Value], _).

%!  gaussian_process_surrogate_options_kappa(+GaussianProcessSurrogateOptions, -Value:float) is det.
%
%   Width (float).
gaussian_process_surrogate_options_kappa(GaussianProcessSurrogateOptions, Value) :-
    '$rosetta_call'(1899, [GaussianProcessSurrogateOptions], Value).

%!  gaussian_process_surrogate_options_set_kappa(+GaussianProcessSurrogateOptions, +Value:float) is det.
%
%   Sets gaussian_process_surrogate_options_kappa/2.
gaussian_process_surrogate_options_set_kappa(GaussianProcessSurrogateOptions, Value) :-
