%   @see `trace_optimize()`, sqp_options_new/1
sqp_optimize(Sqp, Function, Coordinates0, Coordinates, Result) :-
    '$rosetta_call'(2151, [Sqp, Function, '$rosetta_slot'(0, Coordinates0)], Result, Writebacks),
    '$rosetta_out'(Writebacks, 0, Coordinates0, Coordinates).

