%   Pairs ordered the same way by x and y. (integer).
kendall_tau_concordant(KendallTau, Value) :-
    '$rosetta_call'(2282, [KendallTau], Value).

%!  kendall_tau_set_concordant(+KendallTau, +Value:integer) is det.
%
%   Sets kendall_tau_concordant/2.
kendall_tau_set_concordant(KendallTau, Value) :-
