%!  kendall_tau_discordant(+KendallTau, -Value:integer) is det.
%
%   Pairs ordered oppositely by x and y. (integer).
kendall_tau_discordant(KendallTau, Value) :-
    '$rosetta_call'(2284, [KendallTau], Value).

%!  kendall_tau_set_discordant(+KendallTau, +Value:integer) is det.
%
%   Sets kendall_tau_discordant/2.
kendall_tau_set_discordant(KendallTau, Value) :-
