%!  kendall_tau_ties_x(+KendallTau, -Value:integer) is det.
%
%   Pairs tied in x only. (integer).
kendall_tau_ties_x(KendallTau, Value) :-
    '$rosetta_call'(2286, [KendallTau], Value).

%!  kendall_tau_set_ties_x(+KendallTau, +Value:integer) is det.
%
%   Sets kendall_tau_ties_x/2.
kendall_tau_set_ties_x(KendallTau, Value) :-
    '$rosetta_call'(2287, [KendallTau, Value], _).

%!  kendall_tau_ties_y(+KendallTau, -Value:integer) is det.
%
%   Pairs tied in y only. (integer).
kendall_tau_ties_y(KendallTau, Value) :-
    '$rosetta_call'(2288, [KendallTau], Value).

%!  kendall_tau_set_ties_y(+KendallTau, +Value:integer) is det.
%
%   Sets kendall_tau_ties_y/2.
kendall_tau_set_ties_y(KendallTau, Value) :-
    '$rosetta_call'(2289, [KendallTau, Value], _).

%!  kendall_tau_ties_xy(+KendallTau, -Value:integer) is det.
%
%   Pairs tied in both. (integer).
kendall_tau_ties_xy(KendallTau, Value) :-
    '$rosetta_call'(2290, [KendallTau], Value).

%!  kendall_tau_set_ties_xy(+KendallTau, +Value:integer) is det.
%
%   Sets kendall_tau_ties_xy/2.
kendall_tau_set_ties_xy(KendallTau, Value) :-
    '$rosetta_call'(2291, [KendallTau, Value], _).

%!  kendall_tau_tau_a(+KendallTau, -Value:float) is det.
%
%   `(C-D)/\binom n2` (float).
kendall_tau_tau_a(KendallTau, Value) :-
    '$rosetta_call'(2292, [KendallTau], Value).

%!  kendall_tau_set_tau_a(+KendallTau, +Value:float) is det.
%
%   Sets kendall_tau_tau_a/2.
kendall_tau_set_tau_a(KendallTau, Value) :-
    '$rosetta_call'(2293, [KendallTau, Value], _).

%!  kendall_tau_tau_b(+KendallTau, -Value:float) is det.
