% ---------------------------------------------------------------- inla_mixed_model
%
%   SWIG-friendly facade for datamunge::stats::INLAMixedModel — a mixed model (same
%   formula grammar as GLMM/LMM) fit by Integrated Nested Laplace Approximation instead
%   of penalized quasi-likelihood/REML: a genuinely Bayesian alternative returning real
%   posterior means/sds (including for the variance components) rather than point
%   estimates + asymptotic standard errors. See datamunge::bayes::INLA (C++-only, not
%   exposed to bindings -- same reasoning as AutodiffModel) for the underlying algorithm.
%
%   Wraps the C++ class `datamunge::INLAMixedModel`.

%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, +GridPointsPerDim:integer, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, +GridPointsPerDim:integer, +GridSpan:float, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, +GridPointsPerDim:integer, +GridSpan:float, +ModePopulationSize:integer, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, +GridPointsPerDim:integer, +GridSpan:float, +ModePopulationSize:integer, +ModeMaxGenerations:integer, -Object:inla_mixed_model) is det.
%!  inla_mixed_model_new(+Data_:data_frame, +Formula:string, +Family:string, +Strategy:string, +FixedEffectPriorSd:float, +GridPointsPerDim:integer, +GridSpan:float, +ModePopulationSize:integer, +ModeMaxGenerations:integer, +Seed:integer, -Object:inla_mixed_model) is det.
%
%   Calls the C++ constructor `datamunge::INLAMixedModel`.
%
%   Arguments left out take the C++ defaults: Family = "gaussian", Strategy = "grid", FixedEffectPriorSd = 1e+03, GridPointsPerDim = 7, GridSpan = 4.0, ModePopulationSize = 40, ModeMaxGenerations = 200, Seed = 42.
%
%   @arg Family One of "gaussian" (identity link), "binomial" (logit link), or "poisson" (log link).
%   @arg Strategy One of "grid" (integrate over hyperparameter uncertainty) or "eb" (empirical Bayes: fix hyperparameters at their posterior mode).
inla_mixed_model_new(Data_, Formula, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize, ModeMaxGenerations, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize, ModeMaxGenerations], [], [], Object).
inla_mixed_model_new(Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize, ModeMaxGenerations, Seed, Object) :-
    '$rosetta_construct'(2625, [Data_, Formula, Family, Strategy, FixedEffectPriorSd, GridPointsPerDim, GridSpan, ModePopulationSize, ModeMaxGenerations, Seed], [], [], Object).

%!  inla_mixed_model_formula_text(+InlaMixedModel, -Result:string) is det.
%
