cad_scene_triangle_count(CadScene, Result) :-
    '$rosetta_call'(3313, [CadScene], Result).

% ---------------------------------------------------------------- spline_solve_options
%
%   Solver settings shared by fit_tensor_bspline(), fit_tensor_pspline() and the
%   hierarchical fitting methods.
%
%   Wraps the C++ class `datamunge::fda::SplineSolveOptions`.
%
%   *Example*
%
%   ==
%   dm::fda::SplineSolveOptions options;
%   options.method = dm::fda::SplineSolver::Cholesky;
%   ==

%!  spline_solve_options_new(-Object:spline_solve_options) is det.
%
%   Calls the C++ constructor `datamunge::fda::SplineSolveOptions`.
spline_solve_options_new(Object) :-
    '$rosetta_construct'(3323, [], [], [], Object).

%!  spline_solve_options_method(+SplineSolveOptions, -Value:spline_solver) is det.
%
%   Requested solver. (spline_solver).
spline_solve_options_method(SplineSolveOptions, Value) :-
    '$rosetta_call'(3315, [SplineSolveOptions], Value).

%!  spline_solve_options_set_method(+SplineSolveOptions, +Value:spline_solver) is det.
%
%   Sets spline_solve_options_method/2.
spline_solve_options_set_method(SplineSolveOptions, Value) :-
    '$rosetta_call'(3316, [SplineSolveOptions, Value], _).

%!  spline_solve_options_direct_limit(+SplineSolveOptions, -Value:integer) is det.
%
%   Automatic switches from Cholesky to CG above this many unknowns. (integer).
spline_solve_options_direct_limit(SplineSolveOptions, Value) :-
    '$rosetta_call'(3317, [SplineSolveOptions], Value).

%!  spline_solve_options_set_direct_limit(+SplineSolveOptions, +Value:integer) is det.
%
%   Sets spline_solve_options_direct_limit/2.
spline_solve_options_set_direct_limit(SplineSolveOptions, Value) :-
    '$rosetta_call'(3318, [SplineSolveOptions, Value], _).

%!  spline_solve_options_tolerance(+SplineSolveOptions, -Value:float) is det.
%
%   CG relative residual tolerance. (float).
spline_solve_options_tolerance(SplineSolveOptions, Value) :-
    '$rosetta_call'(3319, [SplineSolveOptions], Value).

%!  spline_solve_options_set_tolerance(+SplineSolveOptions, +Value:float) is det.
%
%   Sets spline_solve_options_tolerance/2.
spline_solve_options_set_tolerance(SplineSolveOptions, Value) :-
    '$rosetta_call'(3320, [SplineSolveOptions, Value], _).

%!  spline_solve_options_max_iterations(+SplineSolveOptions, -Value:integer) is det.
%
%   CG iteration cap; 0 means 10 times the unknown count. (integer).
spline_solve_options_max_iterations(SplineSolveOptions, Value) :-
    '$rosetta_call'(3321, [SplineSolveOptions], Value).

%!  spline_solve_options_set_max_iterations(+SplineSolveOptions, +Value:integer) is det.
%
%   Sets spline_solve_options_max_iterations/2.
spline_solve_options_set_max_iterations(SplineSolveOptions, Value) :-
    '$rosetta_call'(3322, [SplineSolveOptions, Value], _).

% ---------------------------------------------------------------- b_spline_refinement
%
%   A refined B-spline basis together with the operator that maps coarse
%   coefficients onto it.
%
%   Wraps the C++ class `datamunge::fda::BSplineRefinement`.
%
%   For any coefficient vector c on the coarse basis, `matrix * c` (equivalently apply())
%   gives coefficients on the refined basis that represent exactly the same spline.
%
%   *Example*
%
%   ==
%   auto coarse = dm::fda::BSplineBasis::open_uniform(2, 4);
%   auto refined = dm::fda::dyadic_refine(coarse);
%   std::print("{}\n", refined.basis.basis_size()); // 6
%   ==

%!  b_spline_refinement_new(-Object:b_spline_refinement) is det.
%
%   Calls the C++ constructor `datamunge::fda::BSplineRefinement`.
b_spline_refinement_new(Object) :-
    '$rosetta_construct'(3327, [], [], [], Object).

%!  b_spline_refinement_apply(+BSplineRefinement, +Coefficients:list(float), -Result:list(float)) is det.
%
%   Maps coarse coefficients to the refined basis.
%
%   Calls the C++ method `datamunge::fda::BSplineRefinement::apply`.
%
%   *Example*
%
%   ==
%   auto r = dm::fda::dyadic_refine(dm::fda::BSplineBasis::open_uniform(1, 2));
%   std::print("{}\n", r.apply({0.0, 2.0})); // [0, 1, 2]
%   ==
%
%   @arg Coefficients One coefficient per coarse basis function.
%   @arg Result One coefficient per refined basis function, representing the same spline.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If `coefficients` does not match the coarse basis size.
b_spline_refinement_apply(BSplineRefinement, Coefficients, Result) :-
    '$rosetta_call'(3324, [BSplineRefinement, Coefficients], Result).

%!  b_spline_refinement_basis(+BSplineRefinement, -Value:b_spline_basis) is det.
%
%   Refined basis (same degree and domain). (b_spline_basis).
b_spline_refinement_basis(BSplineRefinement, Value) :-
    '$rosetta_call'(3325, [BSplineRefinement], Value).

%!  b_spline_refinement_set_basis(+BSplineRefinement, +Value:b_spline_basis) is det.
%
%   Sets b_spline_refinement_basis/2.
b_spline_refinement_set_basis(BSplineRefinement, Value) :-
    '$rosetta_call'(3326, [BSplineRefinement, Value], _).

% ---------------------------------------------------------------- tensor_b_spline
%
%   A scalar tensor-product B-spline f(x) = sum_j c_j B_j(x) with owned coefficients.
%
%   Wraps the C++ class `datamunge::fda::TensorBSpline`.
%
%   With one basis this is an ordinary spline curve; with d bases a surface or volume. The
%   coefficient net is row-major over the per-axis basis sizes (last axis fastest), the same
%   column order as fda::BSpline::evaluate(). Evaluation clamps each coordinate into the
%   basis domain, so points outside the domain take the boundary value. Const methods are
%   safe to call concurrently while the object is not mutated.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);     // linear on [0, 1]
%   dm::fda::TensorBSpline f({b, b}, {0, 1, 1, 2});         // f(x, y) = x + y
%   std::print("{:.2f}\n", f.evaluate({0.25, 0.5}));        // 0.75
%   ==
%
%   *References*
%
%     - C. de Boor (1972). On calculating with B-splines. Journal of Approximation Theory
%       6(1), 50-62. https://doi.org/10.1016/0021-9045(72)90080-9

%!  tensor_b_spline_new(+Basis:(b_spline_basis;list(b_spline_basis)), +Coefficients:list(float), -Object:tensor_b_spline) is det.
%
%   One-dimensional spline curve on `basis`.
%
%   Calls the C++ constructor `datamunge::fda::TensorBSpline`.
%
%   *Example*
%
%   ==
%   dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {1.0, 3.0});
%   std::print("{}\n", f.evaluate(0.5)); // 2
%   ==
%
%   Overloads (C++ picks one by the arguments' types):
%     - `TensorBSpline(+Basis:b_spline_basis, +Coefficients:list(float), -Object)`
%     - `TensorBSpline(+Bases:list(b_spline_basis), +Coefficients:list(float), -Object)`
%
%   @arg Basis Basis for the single axis.
%   @arg Coefficients One coefficient per basis function.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If the coefficient count differs from basis.basis_size().
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If `bases` is empty or the net size does not match.
tensor_b_spline_new(Basis, Coefficients, Object) :-
    '$rosetta_construct'(3341, [Basis, Coefficients], [], [], Object).

%!  tensor_b_spline_dimensions(+TensorBSpline, -Result:integer) is det.
%
%   Number of parameter dimensions d.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::dimensions`.
%
%   @arg Result bases().size().
tensor_b_spline_dimensions(TensorBSpline, Result) :-
    '$rosetta_call'(3328, [TensorBSpline], Result).

%!  tensor_b_spline_bases(+TensorBSpline, -Result:list(b_spline_basis)) is det.
%
%   The per-axis bases.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::bases`.
%
%   @arg Result Reference valid for the lifetime of this object.
tensor_b_spline_bases(TensorBSpline, Result) :-
    '$rosetta_call'(3329, [TensorBSpline], Result).

%!  tensor_b_spline_shape(+TensorBSpline, -Result:list(integer)) is det.
%
%   Per-axis basis sizes, i.e. the shape of the coefficient net.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::shape`.
%
%   @arg Result d sizes in axis order.
tensor_b_spline_shape(TensorBSpline, Result) :-
    '$rosetta_call'(3330, [TensorBSpline], Result).

%!  tensor_b_spline_coefficient_count(+TensorBSpline, -Result:integer) is det.
%
%   Total number of coefficients (product of shape()).
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::coefficient_count`.
%
%   @arg Result Coefficient count.
tensor_b_spline_coefficient_count(TensorBSpline, Result) :-
    '$rosetta_call'(3331, [TensorBSpline], Result).

%!  tensor_b_spline_coefficients(+TensorBSpline, -Result:list(float)) is det.
%
%   The row-major coefficient net.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::coefficients`.
%
%   @arg Result Reference valid until the next mutation of this object.
tensor_b_spline_coefficients(TensorBSpline, Result) :-
    '$rosetta_call'(3332, [TensorBSpline], Result).

%!  tensor_b_spline_domain_min(+TensorBSpline, -Result:list(float)) is det.
%
%   Lower corner of the parameter domain (each basis's first clamped knot).
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::domain_min`.
%
%   @arg Result d coordinates.
tensor_b_spline_domain_min(TensorBSpline, Result) :-
    '$rosetta_call'(3333, [TensorBSpline], Result).

%!  tensor_b_spline_domain_max(+TensorBSpline, -Result:list(float)) is det.
%
%   Upper corner of the parameter domain.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::domain_max`.
%
%   @arg Result d coordinates.
tensor_b_spline_domain_max(TensorBSpline, Result) :-
    '$rosetta_call'(3334, [TensorBSpline], Result).

%!  tensor_b_spline_coefficient(+TensorBSpline, +Index:list(integer), -Result:float) is det.
%
%   Reads one coefficient by per-axis basis index.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::coefficient`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TensorBSpline f({b, b}, {0, 1, 2, 3});
%   std::print("{}\n", f.coefficient({1, 0})); // 2
%   ==
%
%   @arg Index d indices, each in [0, shape()[k]).
%   @arg Result The coefficient.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If index.size() != dimensions().
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If a component is out of range.
tensor_b_spline_coefficient(TensorBSpline, Index, Result) :-
    '$rosetta_call'(3335, [TensorBSpline, Index], Result).

%!  tensor_b_spline_set_coefficient(+TensorBSpline, +Index:list(integer), +Value:float) is det.
%
%   Overwrites one coefficient by per-axis basis index.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::set_coefficient`.
%
%   *Example*
%
%   ==
%   dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {0, 0});
%   f.set_coefficient({1}, 5.0);
%   std::print("{}\n", f.evaluate(1.0)); // 5
%   ==
%
%   @arg Index d indices, each in [0, shape()[k]).
%   @arg Value New coefficient.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If index.size() != dimensions().
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): If a component is out of range.
tensor_b_spline_set_coefficient(TensorBSpline, Index, Value) :-
    '$rosetta_call'(3336, [TensorBSpline, Index, Value], _).

%!  tensor_b_spline_evaluate(+TensorBSpline, +X:(float;list(float)), -Result:float) is det.
%
%   Evaluates a one-dimensional spline at `x` (clamped into the domain).
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::evaluate`.
%
%   *Example*
%
%   ==
%   dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {1.0, 3.0});
%   std::print("{}\n", f.evaluate(2.0)); // 3  (clamped to x = 1)
%   ==
%
%   Overloads (C++ picks one by the arguments' types):
%     - `evaluate(+X:float, -Result:float)`
%     - `evaluate(+Point:list(float), -Result:float)`
%
%   @arg X Finite coordinate.
%   @arg Result f(x).
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If dimensions() != 1 or `x` is not finite.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If point.size() != dimensions() or a coordinate is not finite.
tensor_b_spline_evaluate(TensorBSpline, X, Result) :-
    '$rosetta_call'(3337, [TensorBSpline, X], Result).

%!  tensor_b_spline_evaluate_points(+TensorBSpline, +Points:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates at many points.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::evaluate_points`.
%
%   *Example*
%
%   ==
%   dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(1, 2), {0.0, 1.0});
%   std::print("{}\n", f.evaluate_points({{0.0}, {0.5}})); // [0, 0.5]
%   ==
%
%   @arg Points Points, each of length d.
%   @arg Result One value per point, in input order.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for evaluate(const std::vector<double>&).
tensor_b_spline_evaluate_points(TensorBSpline, Points, Result) :-
    '$rosetta_call'(3338, [TensorBSpline, Points], Result).

%!  tensor_b_spline_evaluate_grid(+TensorBSpline, +Axes:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates on the Cartesian product of per-axis sample values.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::evaluate_grid`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TensorBSpline f({b, b}, {0, 1, 1, 2});
%   std::print("{}\n", f.evaluate_grid({{0, 1}, {0, 1}})); // [0, 1, 1, 2]
%   ==
%
%   @arg Axes d non-empty coordinate lists.
%   @arg Result Row-major grid of values (axis 0 slowest, last axis fastest).
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If axes.size() != dimensions() or an axis is empty.
tensor_b_spline_evaluate_grid(TensorBSpline, Axes, Result) :-
    '$rosetta_call'(3339, [TensorBSpline, Axes], Result).

%!  tensor_b_spline_dyadic_refine(+TensorBSpline, -Result:tensor_b_spline) is det.
%
%   Dyadically refines every axis and maps the coefficients, giving an identical
%   function on the finer, nested tensor basis.
%
%   Calls the C++ method `datamunge::fda::TensorBSpline::dyadic_refine`.
%
%   *Example*
%
%   ==
%   dm::fda::TensorBSpline f(dm::fda::BSplineBasis::open_uniform(2, 4), {0, 1, 3, 2});
%   auto g = f.dyadic_refine();
%   std::print("{} {:.6f}\n", g.coefficient_count(), g.evaluate(0.3) - f.evaluate(0.3)); // 6 0.000000
%   ==
%
%   @arg Result The refined spline.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If some axis basis is not clamped.
%   @see `dyadic_refine(const BSplineBasis&)`
tensor_b_spline_dyadic_refine(TensorBSpline, Result) :-
    '$rosetta_call'(3340, [TensorBSpline], Result).

% ---------------------------------------------------------------- orthant_cell_tree
%
%   Dyadic 2^d-ary tree of axis-aligned boxes shared by the hierarchical splines.
%
%   Wraps the C++ class `datamunge::fda::detail::OrthantCellTree`.
%
%   Cells live in a flat vector and are addressed by id (root 0). Children are created on
%   demand by halving every axis; slot bit k selects the upper half of axis k.

%!  orthant_cell_tree_new(+Lo:list(float), +Hi:list(float), -Object:orthant_cell_tree) is det.
%
%   Creates the root cell [lo, hi].
%
%   Calls the C++ constructor `datamunge::fda::detail::OrthantCellTree`.
%
%   @arg Lo Lower corner.
%   @arg Hi Upper corner, with lo[k] < hi[k].
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty/mismatched/non-finite bounds, lo >= hi, or more than 20 dimensions.
orthant_cell_tree_new(Lo, Hi, Object) :-
    '$rosetta_construct'(3362, [Lo, Hi], [], [], Object).

%!  orthant_cell_tree_dimensions(+OrthantCellTree, -Result:integer) is det.
%
%   Number of dimensions d.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::dimensions`.
%
%   @arg Result d.
orthant_cell_tree_dimensions(OrthantCellTree, Result) :-
    '$rosetta_call'(3342, [OrthantCellTree], Result).

%!  orthant_cell_tree_arity(+OrthantCellTree, -Result:integer) is det.
%
%   Children per cell, 2^d.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::arity`.
%
%   @arg Result 2^d.
orthant_cell_tree_arity(OrthantCellTree, Result) :-
    '$rosetta_call'(3343, [OrthantCellTree], Result).

%!  orthant_cell_tree_size(+OrthantCellTree, -Result:integer) is det.
%
%   Number of cells created so far.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::size`.
%
%   @arg Result Cell count.
orthant_cell_tree_size(OrthantCellTree, Result) :-
    '$rosetta_call'(3344, [OrthantCellTree], Result).

%!  orthant_cell_tree_max_depth(+OrthantCellTree, -Result:integer) is det.
%
%   Greatest depth of any cell.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::max_depth`.
%
%   @arg Result Maximum depth (root is 0).
orthant_cell_tree_max_depth(OrthantCellTree, Result) :-
    '$rosetta_call'(3345, [OrthantCellTree], Result).

%!  orthant_cell_tree_check(+OrthantCellTree, +Cell:integer) is det.
%
%   Throws std::out_of_range unless `cell` is a valid id.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::check`.
%
%   @arg Cell Cell id.
orthant_cell_tree_check(OrthantCellTree, Cell) :-
    '$rosetta_call'(3346, [OrthantCellTree, Cell], _).

%!  orthant_cell_tree_check_slot(+OrthantCellTree, +Slot:integer) is det.
%
%   Throws std::out_of_range unless 0 <= `slot` < arity().
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::check_slot`.
%
%   @arg Slot Child slot.
orthant_cell_tree_check_slot(OrthantCellTree, Slot) :-
    '$rosetta_call'(3347, [OrthantCellTree, Slot], _).

%!  orthant_cell_tree_lo(+OrthantCellTree, +Cell:integer, -Result:list(float)) is det.
%
%   Cell lower corner.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::lo`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
orthant_cell_tree_lo(OrthantCellTree, Cell, Result) :-
    '$rosetta_call'(3348, [OrthantCellTree, Cell], Result).

%!  orthant_cell_tree_hi(+OrthantCellTree, +Cell:integer, -Result:list(float)) is det.
%
%   Cell upper corner.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::hi`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
orthant_cell_tree_hi(OrthantCellTree, Cell, Result) :-
    '$rosetta_call'(3349, [OrthantCellTree, Cell], Result).

%!  orthant_cell_tree_depth(+OrthantCellTree, +Cell:integer, -Result:integer) is det.
%
%   Cell depth.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::depth`.
%
%   @arg Cell Cell id.
%   @arg Result Depth (root 0).
orthant_cell_tree_depth(OrthantCellTree, Cell, Result) :-
    '$rosetta_call'(3350, [OrthantCellTree, Cell], Result).

%!  orthant_cell_tree_parent(+OrthantCellTree, +Cell:integer, -Result:integer) is det.
%
%   Parent id.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::parent`.
%
%   @arg Cell Cell id.
%   @arg Result Parent id, or -1 for the root.
orthant_cell_tree_parent(OrthantCellTree, Cell, Result) :-
    '$rosetta_call'(3351, [OrthantCellTree, Cell], Result).

%!  orthant_cell_tree_child(+OrthantCellTree, +Cell:integer, +Slot:integer, -Result:integer) is det.
%
%   Child id.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::child`.
%
%   @arg Cell Cell id.
%   @arg Slot Child slot.
%   @arg Result Id or -1 if absent.
orthant_cell_tree_child(OrthantCellTree, Cell, Slot, Result) :-
    '$rosetta_call'(3352, [OrthantCellTree, Cell, Slot], Result).

%!  orthant_cell_tree_is_leaf(+OrthantCellTree, +Cell:integer, -Result:boolean) is det.
%
%   True when no child of `cell` exists.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::is_leaf`.
%
%   @arg Cell Cell id.
%   @arg Result Leaf flag.
orthant_cell_tree_is_leaf(OrthantCellTree, Cell, Result) :-
    '$rosetta_call'(3353, [OrthantCellTree, Cell], Result).

%!  orthant_cell_tree_ensure_child(+OrthantCellTree, +Cell:integer, +Slot:integer, -Result:integer) is det.
%
%   Returns the child at `slot`, creating it if needed.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::ensure_child`.
%
%   @arg Cell Parent id.
%   @arg Slot Child slot.
%   @arg Result Child id.
orthant_cell_tree_ensure_child(OrthantCellTree, Cell, Slot, Result) :-
    '$rosetta_call'(3354, [OrthantCellTree, Cell, Slot], Result).

%!  orthant_cell_tree_child_box(+OrthantCellTree, +Cell:integer, +Slot:integer, -Result:pair(list(float), list(float))) is det.
%
%   Box of the (possibly not yet created) child at `slot`.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::child_box`.
%
%   @arg Cell Parent id.
%   @arg Slot Child slot.
%   @arg Result Pair (lo, hi) of the child box.
orthant_cell_tree_child_box(OrthantCellTree, Cell, Slot, Result) :-
    '$rosetta_call'(3355, [OrthantCellTree, Cell, Slot], Result).

%!  orthant_cell_tree_slot_for(+OrthantCellTree, +Cell:integer, +Point:list(float), -Result:integer) is det.
%
%   Slot of `cell's` child that contains `point` (upper half on ties at the max).
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::slot_for`.
%
%   @arg Cell Cell id.
%   @arg Point d coordinates.
%   @arg Result Child slot.
orthant_cell_tree_slot_for(OrthantCellTree, Cell, Point, Result) :-
    '$rosetta_call'(3356, [OrthantCellTree, Cell, Point], Result).

%!  orthant_cell_tree_contains(+OrthantCellTree, +Cell:integer, +Point:list(float), -Result:boolean) is det.
%
%   Whether `point` lies in the closed box of `cell`.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::contains`.
%
%   @arg Cell Cell id.
%   @arg Point d coordinates.
%   @arg Result Containment flag.
orthant_cell_tree_contains(OrthantCellTree, Cell, Point, Result) :-
    '$rosetta_call'(3357, [OrthantCellTree, Cell, Point], Result).

%!  orthant_cell_tree_locate(+OrthantCellTree, +Point:list(float), -Result:integer) is det.
%
%   Deepest existing cell containing `point`.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::locate`.
%
%   @arg Point d coordinates.
%   @arg Result Cell id, or -1 outside the root box.
orthant_cell_tree_locate(OrthantCellTree, Point, Result) :-
    '$rosetta_call'(3358, [OrthantCellTree, Point], Result).

%!  orthant_cell_tree_cells_at_depth(+OrthantCellTree, +Depth:integer, -Result:list(integer)) is det.
%
%   Ids of every cell at `depth`.
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::cells_at_depth`.
%
%   @arg Depth Depth.
%   @arg Result Ids in creation order.
orthant_cell_tree_cells_at_depth(OrthantCellTree, Depth, Result) :-
    '$rosetta_call'(3359, [OrthantCellTree, Depth], Result).

%!  orthant_cell_tree_overlaps(+Lo:list(float), +Hi:list(float), +Blo:list(float), +Bhi:list(float), -Result:boolean) is det.
%
%   Whether the open box (lo, hi) intersects the box [blo, bhi].
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::overlaps`.
%
%   @arg Lo Box A lower corner.
%   @arg Hi Box A upper corner.
%   @arg Blo Box B lower corner.
%   @arg Bhi Box B upper corner.
%   @arg Result True when the interiors overlap.
orthant_cell_tree_overlaps(Lo, Hi, Blo, Bhi, Result) :-
    '$rosetta_call'(3360, [Lo, Hi, Blo, Bhi], Result).

%!  orthant_cell_tree_covered_to_depth(+OrthantCellTree, +TargetDepth:integer, +Blo:list(float), +Bhi:list(float), -Result:boolean) is det.
%
%   Whether the part of [blo, bhi] inside the root is covered by cells of depth
%   >= `target_depth` (i.e. the box lies in the refined domain Omega^target_depth).
%
%   Calls the C++ method `datamunge::fda::detail::OrthantCellTree::covered_to_depth`.
%
%   @arg TargetDepth Depth to test.
%   @arg Blo Box lower corner.
%   @arg Bhi Box upper corner.
%   @arg Result Coverage flag.
orthant_cell_tree_covered_to_depth(OrthantCellTree, TargetDepth, Blo, Bhi, Result) :-
    '$rosetta_call'(3361, [OrthantCellTree, TargetDepth, Blo, Bhi], Result).

% ---------------------------------------------------------------- axis_refinement
%
%   One axis's level-to-level refinement operator stored both ways.
%
%   Wraps the C++ class `datamunge::fda::detail::AxisRefinement`.

%!  axis_refinement_new(-Object:axis_refinement) is det.
%
%   Calls the C++ constructor `datamunge::fda::detail::AxisRefinement`.
axis_refinement_new(Object) :-
    '$rosetta_construct'(3367, [], [], [], Object).

%!  axis_refinement_rows(+AxisRefinement, -Value:list(list(pair(integer, float)))) is det.
%
%   rows[i]: (coarse j, R(i, j)) for refined index i. (list(list(pair(integer, float)))).
axis_refinement_rows(AxisRefinement, Value) :-
    '$rosetta_call'(3363, [AxisRefinement], Value).

%!  axis_refinement_set_rows(+AxisRefinement, +Value:list(list(pair(integer, float)))) is det.
%
%   Sets axis_refinement_rows/2.
axis_refinement_set_rows(AxisRefinement, Value) :-
    '$rosetta_call'(3364, [AxisRefinement, Value], _).

%!  axis_refinement_cols(+AxisRefinement, -Value:list(list(pair(integer, float)))) is det.
%
%   cols[j]: (refined i, R(i, j)) for coarse index j. (list(list(pair(integer, float)))).
axis_refinement_cols(AxisRefinement, Value) :-
    '$rosetta_call'(3365, [AxisRefinement], Value).

%!  axis_refinement_set_cols(+AxisRefinement, +Value:list(list(pair(integer, float)))) is det.
%
%   Sets axis_refinement_cols/2.
axis_refinement_set_cols(AxisRefinement, Value) :-
    '$rosetta_call'(3366, [AxisRefinement, Value], _).

% ---------------------------------------------------------------- hierarchical_b_spline
%
%   Classical (overlay) hierarchical B-spline in the style of Forsey and Bartels:
%   every cell of a dyadic tree may carry its own local "detail" TensorBSpline.
%
%   Wraps the C++ class `datamunge::fda::HierarchicalBSpline`.
%
%   evaluate(x) sums the patch of every cell on the root-to-leaf path containing x. Each
%   patch is evaluated in its cell's local coordinates, (x - cell_min) / (cell_max -
%   cell_min) in [0, 1]^d, so patch bases should span [0, 1]. Patches are independent
%   (no shared nested basis and no truncation); see TruncatedHierarchicalBSpline for the
%   THB-spline construction. Cells are identified by integer ids (root 0).
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   auto b = dm::fda::BSplineBasis::open_uniform(0, 1);              // constant patch
%   h.set_spline(h.root(), dm::fda::TensorBSpline(b, {1.0}));
%   h.refine(h.root(), 1, dm::fda::TensorBSpline(b, {2.0}));          // upper half
%   std::print("{} {}\n", h.evaluate({0.25}), h.evaluate({0.75}));    // 1 3
%   ==
%
%   *References*
%
%     - D. R. Forsey and R. H. Bartels (1988). Hierarchical B-spline refinement. ACM SIGGRAPH
%       Computer Graphics 22(4), 205-212. https://doi.org/10.1145/378456.378512

%!  hierarchical_b_spline_new(+DomainMin:list(float), +DomainMax:list(float), -Object:hierarchical_b_spline) is det.
%
%   Creates a hierarchy whose root cell is [domain_min, domain_max], with no patches.
%
%   Calls the C++ constructor `datamunge::fda::HierarchicalBSpline`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0, 0.0}, {1.0, 2.0});
%   std::print("{} {}\n", h.dimensions(), h.cell_count()); // 2 1
%   ==
%
%   @arg DomainMin Lower corner (length d >= 1).
%   @arg DomainMax Upper corner, with domain_min[k] < domain_max[k].
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty, mismatched or non-finite bounds, min >= max, or more than 20 dimensions.
hierarchical_b_spline_new(DomainMin, DomainMax, Object) :-
    '$rosetta_construct'(3389, [DomainMin, DomainMax], [], [], Object).

%!  hierarchical_b_spline_dimensions(+HierarchicalBSpline, -Result:integer) is det.
%
%   Number of dimensions d.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::dimensions`.
%
%   @arg Result d.
hierarchical_b_spline_dimensions(HierarchicalBSpline, Result) :-
    '$rosetta_call'(3368, [HierarchicalBSpline], Result).

%!  hierarchical_b_spline_cell_count(+HierarchicalBSpline, -Result:integer) is det.
%
%   Number of cells created so far.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::cell_count`.
%
%   @arg Result Cell count.
hierarchical_b_spline_cell_count(HierarchicalBSpline, Result) :-
    '$rosetta_call'(3369, [HierarchicalBSpline], Result).

%!  hierarchical_b_spline_root(+HierarchicalBSpline, -Result:integer) is det.
%
%   Root cell id.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::root`.
%
%   @arg Result Always 0.
hierarchical_b_spline_root(HierarchicalBSpline, Result) :-
    '$rosetta_call'(3370, [HierarchicalBSpline], Result).

%!  hierarchical_b_spline_parent(+HierarchicalBSpline, +Cell:integer, -Result:integer) is det.
%
%   Parent id.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::parent`.
%
%   @arg Cell Cell id.
%   @arg Result Parent id, -1 for the root.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_parent(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3371, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_child(+HierarchicalBSpline, +Cell:integer, +Slot:integer, -Result:integer) is det.
%
%   Child id at `slot`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::child`.
%
%   @arg Cell Cell id.
%   @arg Slot Child slot in [0, 2^d).
%   @arg Result Child id, or -1 when not created.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid ids/slots.
hierarchical_b_spline_child(HierarchicalBSpline, Cell, Slot, Result) :-
    '$rosetta_call'(3372, [HierarchicalBSpline, Cell, Slot], Result).

%!  hierarchical_b_spline_depth(+HierarchicalBSpline, +Cell:integer, -Result:integer) is det.
%
%   Depth of `cell` (root 0).
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::depth`.
%
%   @arg Cell Cell id.
%   @arg Result Depth.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_depth(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3373, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_cell_min(+HierarchicalBSpline, +Cell:integer, -Result:list(float)) is det.
%
%   Lower corner of `cell`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::cell_min`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_cell_min(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3374, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_cell_max(+HierarchicalBSpline, +Cell:integer, -Result:list(float)) is det.
%
%   Upper corner of `cell`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::cell_max`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_cell_max(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3375, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_locate(+HierarchicalBSpline, +Point:list(float), -Result:integer) is det.
%
%   Deepest existing cell containing `point`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::locate`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   int c = h.refine(h.root(), 1);
%   std::print("{} {}\n", h.locate({0.9}) == c, h.locate({2.0})); // true -1
%   ==
%
%   @arg Point d coordinates.
%   @arg Result Cell id, or -1 if `point` is outside the domain.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If point.size() != dimensions().
hierarchical_b_spline_locate(HierarchicalBSpline, Point, Result) :-
    '$rosetta_call'(3376, [HierarchicalBSpline, Point], Result).

%!  hierarchical_b_spline_has_spline(+HierarchicalBSpline, +Cell:integer, -Result:boolean) is det.
%
%   Whether `cell` carries a patch.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::has_spline`.
%
%   @arg Cell Cell id.
%   @arg Result Flag.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_has_spline(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3377, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_spline(+HierarchicalBSpline, +Cell:integer, -Result:tensor_b_spline) is det.
%
%   The patch of `cell`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::spline`.
%
%   @arg Cell Cell id.
%   @arg Result Reference valid until the patch is replaced or cleared.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If no patch.
hierarchical_b_spline_spline(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3378, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_set_spline(+HierarchicalBSpline, +Cell:integer, +Spline:tensor_b_spline) is det.
%
%   Installs (or replaces) the patch of `cell`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::set_spline`.
%
%   @arg Cell Cell id.
%   @arg Spline Patch in cell-local [0, 1]^d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If the patch dimension differs from dimensions().
hierarchical_b_spline_set_spline(HierarchicalBSpline, Cell, Spline) :-
    '$rosetta_call'(3379, [HierarchicalBSpline, Cell, Spline], _).

%!  hierarchical_b_spline_clear_spline(+HierarchicalBSpline, +Cell:integer) is det.
%
%   Removes the patch of `cell` (no-op if none).
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::clear_spline`.
%
%   @arg Cell Cell id.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_clear_spline(HierarchicalBSpline, Cell) :-
    '$rosetta_call'(3380, [HierarchicalBSpline, Cell], _).

%!  hierarchical_b_spline_subdivide(+HierarchicalBSpline, +Cell:integer, -Result:list(integer)) is det.
%
%   Creates all 2^d children of `cell` (existing ones are kept), without patches.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::subdivide`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0, 0.0}, {1.0, 1.0});
%   std::print("{}\n", h.subdivide(h.root()).size()); // 4
%   ==
%
%   @arg Cell Cell id.
%   @arg Result The 2^d child ids in slot order.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
hierarchical_b_spline_subdivide(HierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3381, [HierarchicalBSpline, Cell], Result).

%!  hierarchical_b_spline_refine(+HierarchicalBSpline, +Cell:integer, +Slot:integer, -Result:integer) is det.
%!  hierarchical_b_spline_refine(+HierarchicalBSpline, +Cell:integer, +Slot:integer, +Spline:tensor_b_spline, -Result:integer) is det.
%
%   Creates (if needed) only the child of `cell` at `slot`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::refine`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   int c = h.refine(h.root(), 0);
%   std::print("{}\n", h.cell_max(c)); // [0.5]
%   ==
%
%   Overloads (C++ picks one by the arguments' types):
%     - `refine(+Cell:integer, +Slot:integer, -Result:integer)`
%     - `refine(+Cell:integer, +Slot:integer, +Spline:tensor_b_spline, -Result:integer)`
%
%   @arg Cell Cell id.
%   @arg Slot Child slot; bit k selects the upper half of axis k.
%   @arg Spline Patch for the child.
%   @arg Result The child id.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id or slot.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If the patch dimension differs from dimensions().
hierarchical_b_spline_refine(HierarchicalBSpline, Cell, Slot, Result) :-
    '$rosetta_call'(3382, [HierarchicalBSpline, Cell, Slot], Result).
hierarchical_b_spline_refine(HierarchicalBSpline, Cell, Slot, Spline, Result) :-
    '$rosetta_call'(3382, [HierarchicalBSpline, Cell, Slot, Spline], Result).

%!  hierarchical_b_spline_refine_region(+HierarchicalBSpline, +RegionMin:list(float), +RegionMax:list(float), +Depth:integer) is det.
%!  hierarchical_b_spline_refine_region(+HierarchicalBSpline, +RegionMin:list(float), +RegionMax:list(float), +Depth:integer, +Factory:callable) is det.
%
%   Subdivides, down to depth `depth`, every cell overlapping the open box
%   (region_min, region_max).
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::refine_region`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   h.refine_region({0.0}, {0.3}, 2);
%   std::print("{}\n", h.cell_count()); // 4
%   ==
%
%   Overloads (C++ picks one by the arguments' types):
%     - `refine_region(+RegionMin:list(float), +RegionMax:list(float), +Depth:integer)`
%     - `refine_region(+RegionMin:list(float), +RegionMax:list(float), +Depth:integer, +Factory:callable)`
%
%   @arg RegionMin Lower corner.
%   @arg RegionMax Upper corner (min < max per axis).
%   @arg Depth Deepest depth to create (cells already deeper are untouched).
%   @arg Factory Patch callback; std::nullopt leaves a cell unchanged.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On mismatched sizes or min >= max.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On invalid bounds or a patch of the wrong dimension.
hierarchical_b_spline_refine_region(HierarchicalBSpline, RegionMin, RegionMax, Depth) :-
    '$rosetta_call'(3383, [HierarchicalBSpline, RegionMin, RegionMax, Depth], _).
hierarchical_b_spline_refine_region(HierarchicalBSpline, RegionMin, RegionMax, Depth, Factory) :-
    '$rosetta_call'(3383, [HierarchicalBSpline, RegionMin, RegionMax, Depth, Factory], _).

%!  hierarchical_b_spline_fit_cell(+HierarchicalBSpline, +Cell:integer, +Bases:list(b_spline_basis), +Points:list(list(float)), +Values:list(float)) is det.
%!  hierarchical_b_spline_fit_cell(+HierarchicalBSpline, +Cell:integer, +Bases:list(b_spline_basis), +Points:list(list(float)), +Values:list(float), +Options:spline_solve_options) is det.
%
%   Least-squares fits a new patch on `cell` so the whole hierarchy matches
%   `values` at `points`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::fit_cell`.
%
%   The patch explains only what is left after every other patch on the path (the
%   residual values - evaluate(points)), in the spirit of Forsey-Bartels editing, so pass
%   raw data values rather than residuals. Points are global coordinates inside the cell.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   h.fit_cell(h.root(), {b}, {{0.0}, {1.0}}, {1.0, 3.0});
%   std::print("{}\n", h.evaluate({0.5})); // 2
%   ==
%
%   Arguments left out take the C++ defaults: Options = C++ default.
%
%   @arg Cell Cell id; must not already have a patch (clear_spline() first to refit).
%   @arg Bases Patch bases on [0, 1], one per dimension.
%   @arg Points Sample locations inside the cell.
%   @arg Values One raw data value per point.
%   @arg Options Solver settings.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If the cell has a patch, inputs are empty/mismatched, or a point lies outside the cell.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the local normal equations are singular.
hierarchical_b_spline_fit_cell(HierarchicalBSpline, Cell, Bases, Points, Values) :-
    '$rosetta_call'(3384, [HierarchicalBSpline, Cell, Bases, Points, Values], _).
hierarchical_b_spline_fit_cell(HierarchicalBSpline, Cell, Bases, Points, Values, Options) :-
    '$rosetta_call'(3384, [HierarchicalBSpline, Cell, Bases, Points, Values, Options], _).

%!  hierarchical_b_spline_fit_cell_penalized(+HierarchicalBSpline, +Cell:integer, +Bases:list(b_spline_basis), +Points:list(list(float)), +Values:list(float), +Lambdas:list(float)) is det.
%!  hierarchical_b_spline_fit_cell_penalized(+HierarchicalBSpline, +Cell:integer, +Bases:list(b_spline_basis), +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer) is det.
%!  hierarchical_b_spline_fit_cell_penalized(+HierarchicalBSpline, +Cell:integer, +Bases:list(b_spline_basis), +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer, +Options:spline_solve_options) is det.
%
%   Penalized (P-spline) variant of fit_cell() with per-axis `lambdas` and
%   difference `order`; all-zero lambdas give fit_cell().
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::fit_cell_penalized`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   auto b = dm::fda::BSplineBasis::open_uniform(3, 10);
%   h.fit_cell_penalized(h.root(), {b}, {{0.0}, {1.0}}, {0.0, 2.0}, {1e3});
%   std::print("{:.3f}\n", h.evaluate({0.5})); // 1.000
%   ==
%
%   Arguments left out take the C++ defaults: Order = 2, Options = C++ default.
%
%   @arg Cell Cell id without a patch.
%   @arg Bases Patch bases on [0, 1].
%   @arg Points Sample locations inside the cell.
%   @arg Values Raw data values.
%   @arg Lambdas Nonnegative per-axis weights.
%   @arg Order Difference order (default 2).
%   @arg Options Solver settings.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for fit_cell() and fit_tensor_pspline().
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the penalized normal equations are singular.
hierarchical_b_spline_fit_cell_penalized(HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas) :-
    '$rosetta_call'(3385, [HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas], _).
hierarchical_b_spline_fit_cell_penalized(HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas, Order) :-
    '$rosetta_call'(3385, [HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas, Order], _).
hierarchical_b_spline_fit_cell_penalized(HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas, Order, Options) :-
    '$rosetta_call'(3385, [HierarchicalBSpline, Cell, Bases, Points, Values, Lambdas, Order, Options], _).

%!  hierarchical_b_spline_evaluate(+HierarchicalBSpline, +Point:list(float), -Result:float) is det.
%
%   Sum of the patches along the path of cells containing `point`.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::evaluate`.
%
%   *Example*
%
%   See the class example.
%
%   @arg Point d coordinates inside the domain.
%   @arg Result Hierarchy value (0 where no patch applies).
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a size mismatch or a point outside the domain.
hierarchical_b_spline_evaluate(HierarchicalBSpline, Point, Result) :-
    '$rosetta_call'(3386, [HierarchicalBSpline, Point], Result).

%!  hierarchical_b_spline_evaluate_points(+HierarchicalBSpline, +Points:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates at many points.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::evaluate_points`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0}, {1.0});
%   std::print("{}\n", h.evaluate_points({{0.1}, {0.9}})); // [0, 0]
%   ==
%
%   @arg Points Points of length d.
%   @arg Result One value per point.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for evaluate().
hierarchical_b_spline_evaluate_points(HierarchicalBSpline, Points, Result) :-
    '$rosetta_call'(3387, [HierarchicalBSpline, Points], Result).

%!  hierarchical_b_spline_evaluate_grid(+HierarchicalBSpline, +Axes:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates on a Cartesian grid.
%
%   Calls the C++ method `datamunge::fda::HierarchicalBSpline::evaluate_grid`.
%
%   *Example*
%
%   ==
%   dm::fda::HierarchicalBSpline h({0.0, 0.0}, {1.0, 1.0});
%   std::print("{}\n", h.evaluate_grid({{0.0, 1.0}, {0.5}}).size()); // 2
%   ==
%
%   @arg Axes d non-empty coordinate lists.
%   @arg Result Row-major values (last axis fastest).
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch, empty axis, or outside point.
hierarchical_b_spline_evaluate_grid(HierarchicalBSpline, Axes, Result) :-
    '$rosetta_call'(3388, [HierarchicalBSpline, Axes], Result).

% ---------------------------------------------------------------- truncated_hierarchical_b_spline
%
%   Truncated hierarchical B-spline (THB-spline) of Giannelli, Juttler and Speleers.
%
%   Wraps the C++ class `datamunge::fda::TruncatedHierarchicalBSpline`.
%
%   Level 0 is the caller's TensorBSpline; level l + 1 is the dyadic refinement of level l.
%   A dyadic cell tree defines the nested domains Omega^0 (whole domain) contains Omega^1
%   contains ..., where Omega^l is the union of cells of depth >= l. A level-l basis
%   function is active when its support lies in Omega^l but not in Omega^(l+1). The THB
%   basis consists of the active functions, each truncated: its representation on finer
%   levels drops the finer functions whose support lies in the finer refined domain. The
%   resulting basis is a partition of unity, preserves the continuity of the underlying
%   splines, and spans the hierarchical spline space.
%
%   Internally each level stores a full coefficient net whose entries outside the next
%   level's refined domain always equal the refinement of the coarser level; coefficient
%   edits are pushed down through all finer levels with truncation, so evaluation needs
%   only the finest level covering a point. Refinement never changes the represented
%   function. Bases must be clamped. Cells are integer ids (root 0).
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(2, 4);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline({b, b}, std::vector<double>(16, 1.0)));
%   thb.refine_region({0.0, 0.0}, {0.5, 0.5}, 1);
%   std::print("{} {:.3f}\n", thb.level_count(), thb.evaluate({0.2, 0.2})); // 2 1.000
%   ==
%
%   *References*
%
%     - C. Giannelli, B. Juttler and H. Speleers (2012). THB-splines: The truncated basis for
%       hierarchical splines. Computer Aided Geometric Design 29(7), 485-498.
%       https://doi.org/10.1016/j.cagd.2012.03.025
%     - D. R. Forsey and R. H. Bartels (1988). Hierarchical B-spline refinement.
%       https://doi.org/10.1145/378456.378512

%!  truncated_hierarchical_b_spline_new(+Base:tensor_b_spline, -Object:truncated_hierarchical_b_spline) is det.
%
%   Starts a hierarchy whose level 0 (and root cell / domain) is `base`.
%
%   Calls the C++ constructor `datamunge::fda::TruncatedHierarchicalBSpline`.
%
%   *Example*
%
%   See the class example.
%
%   @arg Base Level-0 spline; every axis basis must be clamped.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If an axis basis is not clamped or d > 20.
truncated_hierarchical_b_spline_new(Base, Object) :-
    '$rosetta_construct'(3419, [Base], [], [], Object).

%!  truncated_hierarchical_b_spline_dimensions(+TruncatedHierarchicalBSpline, -Result:integer) is det.
%
%   Number of dimensions d.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::dimensions`.
%
%   @arg Result d.
truncated_hierarchical_b_spline_dimensions(TruncatedHierarchicalBSpline, Result) :-
    '$rosetta_call'(3390, [TruncatedHierarchicalBSpline], Result).

%!  truncated_hierarchical_b_spline_level_count(+TruncatedHierarchicalBSpline, -Result:integer) is det.
%
%   Number of materialized levels (1 + deepest cell depth).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::level_count`.
%
%   @arg Result Level count.
truncated_hierarchical_b_spline_level_count(TruncatedHierarchicalBSpline, Result) :-
    '$rosetta_call'(3391, [TruncatedHierarchicalBSpline], Result).

%!  truncated_hierarchical_b_spline_level(+TruncatedHierarchicalBSpline, +Level:integer, -Result:tensor_b_spline) is det.
%
%   The level- `l` spline on the whole domain; it equals the hierarchy wherever
%   Omega^l but not Omega^(l+1) applies.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::level`.
%
%   @arg Level Level in [0, level_count()).
%   @arg Result Reference valid until the next refinement or coefficient edit.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid level.
truncated_hierarchical_b_spline_level(TruncatedHierarchicalBSpline, Level, Result) :-
    '$rosetta_call'(3392, [TruncatedHierarchicalBSpline, Level], Result).

%!  truncated_hierarchical_b_spline_cell_count(+TruncatedHierarchicalBSpline, -Result:integer) is det.
%
%   Number of cells.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::cell_count`.
%
%   @arg Result Cell count.
truncated_hierarchical_b_spline_cell_count(TruncatedHierarchicalBSpline, Result) :-
    '$rosetta_call'(3393, [TruncatedHierarchicalBSpline], Result).

%!  truncated_hierarchical_b_spline_root(+TruncatedHierarchicalBSpline, -Result:integer) is det.
%
%   Root cell id.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::root`.
%
%   @arg Result Always 0.
truncated_hierarchical_b_spline_root(TruncatedHierarchicalBSpline, Result) :-
    '$rosetta_call'(3394, [TruncatedHierarchicalBSpline], Result).

%!  truncated_hierarchical_b_spline_parent(+TruncatedHierarchicalBSpline, +Cell:integer, -Result:integer) is det.
%
%   Parent id.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::parent`.
%
%   @arg Cell Cell id.
%   @arg Result Parent id, -1 for the root.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
truncated_hierarchical_b_spline_parent(TruncatedHierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3395, [TruncatedHierarchicalBSpline, Cell], Result).

%!  truncated_hierarchical_b_spline_child(+TruncatedHierarchicalBSpline, +Cell:integer, +Slot:integer, -Result:integer) is det.
%
%   Child id.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::child`.
%
%   @arg Cell Cell id.
%   @arg Slot Child slot.
%   @arg Result Child id or -1.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid ids/slots.
truncated_hierarchical_b_spline_child(TruncatedHierarchicalBSpline, Cell, Slot, Result) :-
    '$rosetta_call'(3396, [TruncatedHierarchicalBSpline, Cell, Slot], Result).

%!  truncated_hierarchical_b_spline_depth(+TruncatedHierarchicalBSpline, +Cell:integer, -Result:integer) is det.
%
%   Depth (= level used there if it is a leaf).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::depth`.
%
%   @arg Cell Cell id.
%   @arg Result Depth.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
truncated_hierarchical_b_spline_depth(TruncatedHierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3397, [TruncatedHierarchicalBSpline, Cell], Result).

%!  truncated_hierarchical_b_spline_cell_min(+TruncatedHierarchicalBSpline, +Cell:integer, -Result:list(float)) is det.
%
%   Lower corner.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::cell_min`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
truncated_hierarchical_b_spline_cell_min(TruncatedHierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3398, [TruncatedHierarchicalBSpline, Cell], Result).

%!  truncated_hierarchical_b_spline_cell_max(+TruncatedHierarchicalBSpline, +Cell:integer, -Result:list(float)) is det.
%
%   Upper corner.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::cell_max`.
%
%   @arg Cell Cell id.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
truncated_hierarchical_b_spline_cell_max(TruncatedHierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3399, [TruncatedHierarchicalBSpline, Cell], Result).

%!  truncated_hierarchical_b_spline_locate(+TruncatedHierarchicalBSpline, +Point:list(float), -Result:integer) is det.
%
%   Deepest cell containing `point` (its depth is the finest level there).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::locate`.
%
%   @arg Point d coordinates.
%   @arg Result Cell id, or -1 outside the domain.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): If point.size() != dimensions().
truncated_hierarchical_b_spline_locate(TruncatedHierarchicalBSpline, Point, Result) :-
    '$rosetta_call'(3400, [TruncatedHierarchicalBSpline, Point], Result).

%!  truncated_hierarchical_b_spline_refine(+TruncatedHierarchicalBSpline, +Cell:integer, +Slot:integer, -Result:integer) is det.
%
%   Creates (if needed) the child of `cell` at `slot`, materializing the next
%   level when first reached. The represented function is unchanged.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::refine`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   thb.refine(thb.root(), 0);
%   std::print("{} {}\n", thb.level_count(), thb.evaluate({0.25})); // 2 0.25
%   ==
%
%   @arg Cell Cell id.
%   @arg Slot Child slot.
%   @arg Result Child id.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id or slot.
truncated_hierarchical_b_spline_refine(TruncatedHierarchicalBSpline, Cell, Slot, Result) :-
    '$rosetta_call'(3401, [TruncatedHierarchicalBSpline, Cell, Slot], Result).

%!  truncated_hierarchical_b_spline_subdivide(+TruncatedHierarchicalBSpline, +Cell:integer, -Result:list(integer)) is det.
%
%   Creates all 2^d children of `cell`.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::subdivide`.
%
%   *Example*
%
%   See refine().
%
%   @arg Cell Cell id.
%   @arg Result Child ids in slot order.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid id.
truncated_hierarchical_b_spline_subdivide(TruncatedHierarchicalBSpline, Cell, Result) :-
    '$rosetta_call'(3402, [TruncatedHierarchicalBSpline, Cell], Result).

%!  truncated_hierarchical_b_spline_refine_region(+TruncatedHierarchicalBSpline, +RegionMin:list(float), +RegionMax:list(float), +Depth:integer) is det.
%
%   Subdivides, down to depth `depth`, every cell overlapping the open box
%   (region_min, region_max). The represented function is unchanged.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::refine_region`.
%
%   *Example*
%
%   See the class example.
%
%   @arg RegionMin Lower corner.
%   @arg RegionMax Upper corner (min < max per axis).
%   @arg Depth Deepest level to create.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On mismatched sizes or min >= max.
truncated_hierarchical_b_spline_refine_region(TruncatedHierarchicalBSpline, RegionMin, RegionMax, Depth) :-
    '$rosetta_call'(3403, [TruncatedHierarchicalBSpline, RegionMin, RegionMax, Depth], _).

%!  truncated_hierarchical_b_spline_support_min(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), -Result:list(float)) is det.
%
%   Lower corner of the support box of basis function `index` at `level`.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::support_min`.
%
%   @arg Level Level.
%   @arg Index Multi-index into that level's net.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch.
truncated_hierarchical_b_spline_support_min(TruncatedHierarchicalBSpline, Level, Index, Result) :-
    '$rosetta_call'(3404, [TruncatedHierarchicalBSpline, Level, Index], Result).

%!  truncated_hierarchical_b_spline_support_max(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), -Result:list(float)) is det.
%
%   Upper corner of the support box.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::support_max`.
%
%   @arg Level Level.
%   @arg Index Multi-index.
%   @arg Result d coordinates.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch.
truncated_hierarchical_b_spline_support_max(TruncatedHierarchicalBSpline, Level, Index, Result) :-
    '$rosetta_call'(3405, [TruncatedHierarchicalBSpline, Level, Index], Result).

%!  truncated_hierarchical_b_spline_is_active(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), -Result:boolean) is det.
%
%   Whether level- `level` function `index` is in the THB basis (support in
%   Omega^level but not in Omega^(level+1)).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::is_active`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   thb.subdivide(thb.root());
%   std::print("{} {}\n", thb.is_active(0, {0}), thb.is_active(1, {0})); // false true
%   ==
%
%   @arg Level Level.
%   @arg Index Multi-index.
%   @arg Result Activity flag.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch.
truncated_hierarchical_b_spline_is_active(TruncatedHierarchicalBSpline, Level, Index, Result) :-
    '$rosetta_call'(3406, [TruncatedHierarchicalBSpline, Level, Index], Result).

%!  truncated_hierarchical_b_spline_active_indices(+TruncatedHierarchicalBSpline, +Level:integer, -Result:list(list(integer))) is det.
%
%   Every active multi-index at `level`, in row-major order.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::active_indices`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   std::print("{}\n", thb.active_indices(0).size()); // 2
%   ==
%
%   @arg Level Level.
%   @arg Result Multi-indices.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid level.
truncated_hierarchical_b_spline_active_indices(TruncatedHierarchicalBSpline, Level, Result) :-
    '$rosetta_call'(3407, [TruncatedHierarchicalBSpline, Level], Result).

%!  truncated_hierarchical_b_spline_basis_size(+TruncatedHierarchicalBSpline, -Result:integer) is det.
%
%   Total number of THB basis functions over all levels.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::basis_size`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   thb.refine(thb.root(), 0);
%   std::print("{}\n", thb.basis_size()); // 3
%   ==
%
%   @arg Result Count.
truncated_hierarchical_b_spline_basis_size(TruncatedHierarchicalBSpline, Result) :-
    '$rosetta_call'(3408, [TruncatedHierarchicalBSpline], Result).

%!  truncated_hierarchical_b_spline_coefficient(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), -Result:float) is det.
%
%   THB coefficient of a basis function (for active functions; inactive entries
%   are internal bookkeeping).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::coefficient`.
%
%   @arg Level Level.
%   @arg Index Multi-index.
%   @arg Result Coefficient.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch.
truncated_hierarchical_b_spline_coefficient(TruncatedHierarchicalBSpline, Level, Index, Result) :-
    '$rosetta_call'(3409, [TruncatedHierarchicalBSpline, Level, Index], Result).

%!  truncated_hierarchical_b_spline_set_coefficient(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), +Value:float) is det.
%
%   Sets the coefficient of an active function and propagates the change, with
%   truncation, to every finer level. The edit is local to the function's support.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::set_coefficient`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 0.0}));
%   thb.set_coefficient(0, {1}, 2.0);
%   std::print("{}\n", thb.evaluate({0.5})); // 1
%   ==
%
%   @arg Level Level.
%   @arg Index Active multi-index.
%   @arg Value New coefficient.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch or an inactive index.
truncated_hierarchical_b_spline_set_coefficient(TruncatedHierarchicalBSpline, Level, Index, Value) :-
    '$rosetta_call'(3410, [TruncatedHierarchicalBSpline, Level, Index, Value], _).

%!  truncated_hierarchical_b_spline_truncated_basis(+TruncatedHierarchicalBSpline, +Level:integer, +Index:list(integer), +Point:list(float), -Result:float) is det.
%
%   Value of the truncated basis function (level, index) at `point`.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::truncated_basis`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   std::print("{}\n", thb.truncated_basis(0, {1}, {0.25})); // 0.25
%   ==
%
%   @arg Level Level.
%   @arg Index Multi-index (inactive functions give 0).
%   @arg Point d coordinates inside the domain.
%   @arg Result Truncated basis value.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For invalid levels/indices.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a size mismatch or a point outside the domain.
truncated_hierarchical_b_spline_truncated_basis(TruncatedHierarchicalBSpline, Level, Index, Point, Result) :-
    '$rosetta_call'(3411, [TruncatedHierarchicalBSpline, Level, Index, Point], Result).

%!  truncated_hierarchical_b_spline_fit_level(+TruncatedHierarchicalBSpline, +Level:integer, +Points:list(list(float)), +Values:list(float)) is det.
%!  truncated_hierarchical_b_spline_fit_level(+TruncatedHierarchicalBSpline, +Level:integer, +Points:list(list(float)), +Values:list(float), +Options:spline_solve_options) is det.
%
%   Least-squares update of the active coefficients at `level` only.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::fit_level`.
%
%   Solves for the change of the level's active coefficients that best explains the
%   residual values - evaluate(points), using the exact truncated basis, so pass raw
%   data values. Points shallower than `level` are unaffected by these functions and
%   are ignored. Typical use is coarse-to-fine: fit level 0, refine where residuals are
%   large, then fit the new level.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 0.0}));
%   thb.fit_level(0, {{0.0}, {1.0}}, {1.0, 3.0});
%   std::print("{}\n", thb.evaluate({0.5})); // 2
%   ==
%
%   Arguments left out take the C++ defaults: Options = C++ default.
%
%   @arg Level Level with at least one active function.
%   @arg Points Sample locations inside the domain.
%   @arg Values One raw value per point.
%   @arg Options Solver settings.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid level.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty/mismatched inputs, points outside the domain, or a level with no active functions.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the normal equations are singular.
truncated_hierarchical_b_spline_fit_level(TruncatedHierarchicalBSpline, Level, Points, Values) :-
    '$rosetta_call'(3412, [TruncatedHierarchicalBSpline, Level, Points, Values], _).
truncated_hierarchical_b_spline_fit_level(TruncatedHierarchicalBSpline, Level, Points, Values, Options) :-
    '$rosetta_call'(3412, [TruncatedHierarchicalBSpline, Level, Points, Values, Options], _).

%!  truncated_hierarchical_b_spline_fit_level_penalized(+TruncatedHierarchicalBSpline, +Level:integer, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float)) is det.
%!  truncated_hierarchical_b_spline_fit_level_penalized(+TruncatedHierarchicalBSpline, +Level:integer, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer) is det.
%!  truncated_hierarchical_b_spline_fit_level_penalized(+TruncatedHierarchicalBSpline, +Level:integer, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer, +Options:spline_solve_options) is det.
%
%   Penalized variant of fit_level(): adds the level's full-grid tensor difference
%   penalty restricted to its active functions, applied to the coefficient change.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::fit_level_penalized`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(3, 8);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, std::vector<double>(8, 0.0)));
%   thb.fit_level_penalized(0, {{0.0}, {1.0}}, {0.0, 1.0}, {1e3});
%   std::print("{:.3f}\n", thb.evaluate({0.5})); // 0.500
%   ==
%
%   Arguments left out take the C++ defaults: Order = 2, Options = C++ default.
%
%   @arg Level Level.
%   @arg Points Sample locations.
%   @arg Values Raw values.
%   @arg Lambdas Nonnegative per-axis weights.
%   @arg Order Difference order (default 2).
%   @arg Options Solver settings.
%   @throws error(native_error(out_of_range, Message), _) (C++ `std::out_of_range`): For an invalid level.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for fit_level() and tensor_difference_penalty().
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the normal equations are singular.
truncated_hierarchical_b_spline_fit_level_penalized(TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas) :-
    '$rosetta_call'(3413, [TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas], _).
truncated_hierarchical_b_spline_fit_level_penalized(TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas, Order) :-
    '$rosetta_call'(3413, [TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas, Order], _).
truncated_hierarchical_b_spline_fit_level_penalized(TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas, Order, Options) :-
    '$rosetta_call'(3413, [TruncatedHierarchicalBSpline, Level, Points, Values, Lambdas, Order, Options], _).

%!  truncated_hierarchical_b_spline_fit(+TruncatedHierarchicalBSpline, +Points:list(list(float)), +Values:list(float)) is det.
%!  truncated_hierarchical_b_spline_fit(+TruncatedHierarchicalBSpline, +Points:list(list(float)), +Values:list(float), +Options:spline_solve_options) is det.
%
%   Least-squares fit of every active coefficient on every level at once
%   (replaces the current function).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::fit`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 0.0}));
%   thb.refine(thb.root(), 1);                      // adds a knot at 0.5
%   thb.fit({{0.0}, {0.25}, {0.5}, {0.75}, {1.0}}, {1.0, 0.5, 0.0, 0.5, 1.0}); // |2x - 1|
%   std::print("{:.3f}\n", thb.evaluate({0.75})); // 0.500
%   ==
%
%   Arguments left out take the C++ defaults: Options = C++ default.
%
%   @arg Points Sample locations inside the domain.
%   @arg Values One value per point.
%   @arg Options Solver settings.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On empty/mismatched inputs or points outside the domain.
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If some active function has too little data (singular).
truncated_hierarchical_b_spline_fit(TruncatedHierarchicalBSpline, Points, Values) :-
    '$rosetta_call'(3414, [TruncatedHierarchicalBSpline, Points, Values], _).
truncated_hierarchical_b_spline_fit(TruncatedHierarchicalBSpline, Points, Values, Options) :-
    '$rosetta_call'(3414, [TruncatedHierarchicalBSpline, Points, Values, Options], _).

%!  truncated_hierarchical_b_spline_fit_penalized(+TruncatedHierarchicalBSpline, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float)) is det.
%!  truncated_hierarchical_b_spline_fit_penalized(+TruncatedHierarchicalBSpline, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer) is det.
%!  truncated_hierarchical_b_spline_fit_penalized(+TruncatedHierarchicalBSpline, +Points:list(list(float)), +Values:list(float), +Lambdas:list(float), +Order:integer, +Options:spline_solve_options) is det.
%
%   Penalized all-level fit: adds lambda_k times the squared order-q differences
%   along axis k of every run of q + 1 neighbouring active coefficients of a level.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::fit_penalized`.
%
%   Differences that would involve an inactive coefficient are omitted, so for q >= 1
%   constant coefficients (and, generally, polynomials of degree < q in the coefficient
%   index on each level) are unpenalized; q = 0 is ridge regression on all coefficients.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(2, 6);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, std::vector<double>(6, 0.0)));
%   thb.refine_region({0.0}, {0.5}, 1);
%   thb.fit_penalized({{0.0}, {1.0}}, {2.0, 2.0}, {1.0}, 1);
%   std::print("{:.3f}\n", thb.evaluate({0.3})); // 2.000
%   ==
%
%   Arguments left out take the C++ defaults: Order = 2, Options = C++ default.
%
%   @arg Points Sample locations.
%   @arg Values One value per point.
%   @arg Lambdas Nonnegative per-axis weights.
%   @arg Order Difference order (default 2).
%   @arg Options Solver settings.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for fit() and tensor_difference_penalty().
%   @throws error(native_error(native, Message), _) (C++ `std::runtime_error`): If the normal equations are singular.
truncated_hierarchical_b_spline_fit_penalized(TruncatedHierarchicalBSpline, Points, Values, Lambdas) :-
    '$rosetta_call'(3415, [TruncatedHierarchicalBSpline, Points, Values, Lambdas], _).
truncated_hierarchical_b_spline_fit_penalized(TruncatedHierarchicalBSpline, Points, Values, Lambdas, Order) :-
    '$rosetta_call'(3415, [TruncatedHierarchicalBSpline, Points, Values, Lambdas, Order], _).
truncated_hierarchical_b_spline_fit_penalized(TruncatedHierarchicalBSpline, Points, Values, Lambdas, Order, Options) :-
    '$rosetta_call'(3415, [TruncatedHierarchicalBSpline, Points, Values, Lambdas, Order, Options], _).

%!  truncated_hierarchical_b_spline_evaluate(+TruncatedHierarchicalBSpline, +Point:list(float), -Result:float) is det.
%
%   Evaluates the hierarchical spline (finest level covering `point`).
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::evaluate`.
%
%   *Example*
%
%   See the class example.
%
%   @arg Point d coordinates inside the domain.
%   @arg Result Value.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a size mismatch or a point outside the domain.
truncated_hierarchical_b_spline_evaluate(TruncatedHierarchicalBSpline, Point, Result) :-
    '$rosetta_call'(3416, [TruncatedHierarchicalBSpline, Point], Result).

%!  truncated_hierarchical_b_spline_evaluate_points(+TruncatedHierarchicalBSpline, +Points:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates at many points.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::evaluate_points`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   std::print("{}\n", thb.evaluate_points({{0.0}, {0.5}})); // [0, 0.5]
%   ==
%
%   @arg Points Points of length d.
%   @arg Result One value per point.
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): As for evaluate().
truncated_hierarchical_b_spline_evaluate_points(TruncatedHierarchicalBSpline, Points, Result) :-
    '$rosetta_call'(3417, [TruncatedHierarchicalBSpline, Points], Result).

%!  truncated_hierarchical_b_spline_evaluate_grid(+TruncatedHierarchicalBSpline, +Axes:list(list(float)), -Result:list(float)) is det.
%
%   Evaluates on a Cartesian grid.
%
%   Calls the C++ method `datamunge::fda::TruncatedHierarchicalBSpline::evaluate_grid`.
%
%   *Example*
%
%   ==
%   auto b = dm::fda::BSplineBasis::open_uniform(1, 2);
%   dm::fda::TruncatedHierarchicalBSpline thb(dm::fda::TensorBSpline(b, {0.0, 1.0}));
%   std::print("{}\n", thb.evaluate_grid({{0.0, 1.0}})); // [0, 1]
%   ==
%
%   @arg Axes d non-empty coordinate lists.
%   @arg Result Row-major values (last axis fastest).
%   @throws error(native_error(invalid_argument, Message), _) (C++ `std::invalid_argument`): On a dimension mismatch, empty axis, or outside point.
truncated_hierarchical_b_spline_evaluate_grid(TruncatedHierarchicalBSpline, Axes, Result) :-
    '$rosetta_call'(3418, [TruncatedHierarchicalBSpline, Axes], Result).

% ---------------------------------------------------------------- nn_tensor
%
%   Wraps the C++ class `datamunge::nn::NnTensor`.

%!  nn_tensor_new(-Object:nn_tensor) is det.
%!  nn_tensor_new(+Values:list(float), -Object:nn_tensor) is det.
%!  nn_tensor_new(+Values:list(float), +Shape:list(integer), -Object:nn_tensor) is det.
%!  nn_tensor_new(+Values:list(float), +Shape:list(integer), +Dtype:string, -Object:nn_tensor) is det.
%
%   An empty (undefined) tensor.
%
%   Calls the C++ constructor `datamunge::nn::NnTensor`.
%
%   Overloads (C++ picks one by the arguments' types):
%     - `NnTensor(-Object)`
%     - `NnTensor(+Values:list(float), +Shape:list(integer), +Dtype:string = "float32", -Object)`
nn_tensor_new(Object) :-
    '$rosetta_construct'(3474, [], [], [], Object).
nn_tensor_new(Values, Object) :-
    '$rosetta_construct'(3474, [Values], [], [], Object).
nn_tensor_new(Values, Shape, Object) :-
    '$rosetta_construct'(3474, [Values, Shape], [], [], Object).
nn_tensor_new(Values, Shape, Dtype, Object) :-
    '$rosetta_construct'(3474, [Values, Shape, Dtype], [], [], Object).

%!  nn_tensor_zeros(+Shape:list(integer), -Result:nn_tensor) is det.
